-- PostgreSQL testing baseline for the existing hospital backend. Contains schema only; no operating records.

CREATE TABLE "accommodation_assessments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "admission_id" BIGINT NOT NULL CHECK ("admission_id" >= 0),
    "source_key" __CITEXT_TYPE__ NOT NULL CHECK (char_length("source_key") <= 64),
    "status" __CITEXT_TYPE__ NOT NULL CHECK (char_length("status") <= 24),
    "total_kobo" BIGINT CHECK ("total_kobo" >= 0),
    "snapshot" JSONB NOT NULL,
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "admission_exit_types" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "admission_id" BIGINT NOT NULL CHECK ("admission_id" >= 0),
    "exit_type" __CITEXT_TYPE__ NOT NULL CHECK (char_length("exit_type") <= 16),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "admission_revisions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "admission_id" BIGINT NOT NULL CHECK ("admission_id" >= 0),
    "workflow_version" BIGINT NOT NULL CHECK ("workflow_version" >= 0),
    "operation" __CITEXT_TYPE__ NOT NULL CHECK (char_length("operation") <= 32),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "reason" TEXT NOT NULL,
    "snapshot" JSONB NOT NULL,
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "admissions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "encounter_id" BIGINT NOT NULL CHECK ("encounter_id" >= 0),
    "patient_id" BIGINT NOT NULL CHECK ("patient_id" >= 0),
    "status" VARCHAR(24) COLLATE "C" DEFAULT 'admitted' NOT NULL,
    "admitted_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "admitted_by" BIGINT NOT NULL CHECK ("admitted_by" >= 0),
    "authorized_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "authorized_by" BIGINT CHECK ("authorized_by" >= 0),
    "discharged_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "discharged_by" BIGINT CHECK ("discharged_by" >= 0),
    "discharge_reason" TEXT,
    "discharge_summary" TEXT,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "active_patient_id" BIGINT GENERATED ALWAYS AS ((case when ("status" in ('admitted','discharge_authorized')) then "patient_id" else NULL end)) STORED CHECK ("active_patient_id" >= 0),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("id")
);

CREATE TABLE "allocation_rates" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "allocation_id" BIGINT NOT NULL CHECK ("allocation_id" >= 0),
    "daily_rate_kobo" BIGINT CHECK ("daily_rate_kobo" >= 0),
    "source" __CITEXT_TYPE__ NOT NULL CHECK (char_length("source") <= 16),
    "source_version" BIGINT CHECK ("source_version" >= 0),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "appointment_follow_ups" (
    "appointment_id" BIGINT NOT NULL CHECK ("appointment_id" >= 0),
    "previous_appointment_id" BIGINT NOT NULL CHECK ("previous_appointment_id" >= 0),
    "created_by" BIGINT NOT NULL CHECK ("created_by" >= 0),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY ("appointment_id")
);

CREATE TABLE "appointment_revisions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "appointment_id" BIGINT NOT NULL CHECK ("appointment_id" >= 0),
    "version" BIGINT NOT NULL CHECK ("version" >= 0),
    "operation" __CITEXT_TYPE__ NOT NULL CHECK (char_length("operation") <= 16),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "reason" TEXT,
    "snapshot" JSONB NOT NULL,
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "appointments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "first_name" __CITEXT_TYPE__ NOT NULL CHECK (char_length("first_name") <= 64),
    "last_name" __CITEXT_TYPE__ NOT NULL CHECK (char_length("last_name") <= 64),
    "phone" __CITEXT_TYPE__ NOT NULL CHECK (char_length("phone") <= 32),
    "starts_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "ends_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "booking_channel" __CITEXT_TYPE__ NOT NULL CHECK (char_length("booking_channel") <= 64),
    "visit_type" __CITEXT_TYPE__ NOT NULL CHECK (char_length("visit_type") <= 64),
    "specialist_name" __CITEXT_TYPE__ CHECK (char_length("specialist_name") <= 191),
    "specialist_email" __CITEXT_TYPE__ CHECK (char_length("specialist_email") <= 191),
    "status" VARCHAR(16) COLLATE "C" DEFAULT 'booked' NOT NULL,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "patient_id" BIGINT CHECK ("patient_id" >= 0),
    "doctor_id" BIGINT CHECK ("doctor_id" >= 0),
    "booked_by" BIGINT NOT NULL CHECK ("booked_by" >= 0),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("id")
);

CREATE TABLE "audit_events" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "action" __CITEXT_TYPE__ NOT NULL CHECK (char_length("action") <= 64),
    "outcome" __CITEXT_TYPE__ NOT NULL CHECK (char_length("outcome") <= 16),
    "channel" __CITEXT_TYPE__ NOT NULL CHECK (char_length("channel") <= 16),
    "actor_id" BIGINT CHECK ("actor_id" >= 0),
    "subject_type" __CITEXT_TYPE__ NOT NULL CHECK (char_length("subject_type") <= 32),
    "subject_id" BIGINT CHECK ("subject_id" >= 0),
    "request_id" __CITEXT_TYPE__ NOT NULL CHECK (char_length("request_id") <= 36),
    "http_status" INTEGER CHECK ("http_status" >= 0),
    "safe_summary" JSONB NOT NULL,
    "occurred_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "bed_allocations" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "bed_id" BIGINT NOT NULL CHECK ("bed_id" >= 0),
    "admission_id" BIGINT NOT NULL CHECK ("admission_id" >= 0),
    "assigned_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "assigned_by" BIGINT NOT NULL CHECK ("assigned_by" >= 0),
    "assignment_reason" TEXT NOT NULL,
    "released_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "released_by" BIGINT CHECK ("released_by" >= 0),
    "release_reason" TEXT,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "current_bed_id" BIGINT GENERATED ALWAYS AS ((case when ("released_at" is null) then "bed_id" else NULL end)) STORED CHECK ("current_bed_id" >= 0),
    "current_admission_id" BIGINT GENERATED ALWAYS AS ((case when ("released_at" is null) then "admission_id" else NULL end)) STORED CHECK ("current_admission_id" >= 0),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("id")
);

CREATE TABLE "beds" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "ward_id" BIGINT NOT NULL CHECK ("ward_id" >= 0),
    "label" __CITEXT_TYPE__ NOT NULL CHECK (char_length("label") <= 64),
    "daily_rate" DECIMAL(14,2),
    "is_active" SMALLINT DEFAULT 1 NOT NULL,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_accounts" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "patient_id" BIGINT NOT NULL CHECK ("patient_id" >= 0),
    "currency" __CITEXT_TYPE__ DEFAULT 'NGN' NOT NULL CHECK (char_length("currency") <= 3),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_allocation_releases" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "allocation_id" BIGINT NOT NULL CHECK ("allocation_id" >= 0),
    "review_id" BIGINT NOT NULL CHECK ("review_id" >= 0),
    "amount_kobo" BIGINT NOT NULL CHECK ("amount_kobo" >= 0),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_allocations" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "receipt_id" BIGINT NOT NULL CHECK ("receipt_id" >= 0),
    "invoice_id" BIGINT NOT NULL CHECK ("invoice_id" >= 0),
    "amount_kobo" BIGINT NOT NULL CHECK ("amount_kobo" >= 0),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_change_reviews" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "change_id" BIGINT NOT NULL CHECK ("change_id" >= 0),
    "decision" __CITEXT_TYPE__ NOT NULL CHECK (char_length("decision") <= 16),
    "payout_reference" __CITEXT_TYPE__ CHECK (char_length("payout_reference") <= 128),
    "payout_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "payout_confirmed" SMALLINT DEFAULT 0 NOT NULL,
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    "payout_key" __CITEXT_TYPE__ CHECK (char_length("payout_key") <= 64),
    "payout_method" __CITEXT_TYPE__ CHECK (char_length("payout_method") <= 24),
    "payee_name" __CITEXT_TYPE__ CHECK (char_length("payee_name") <= 191),
    "payout_details" JSONB,
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_changes" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "account_id" BIGINT NOT NULL CHECK ("account_id" >= 0),
    "kind" __CITEXT_TYPE__ NOT NULL CHECK (char_length("kind") <= 16),
    "item_id" BIGINT CHECK ("item_id" >= 0),
    "receipt_id" BIGINT CHECK ("receipt_id" >= 0),
    "amount_kobo" BIGINT NOT NULL CHECK ("amount_kobo" >= 0),
    "replacement_quantity_micros" BIGINT CHECK ("replacement_quantity_micros" >= 0),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_events" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "account_id" BIGINT NOT NULL CHECK ("account_id" >= 0),
    "version" BIGINT NOT NULL CHECK ("version" >= 0),
    "action" __CITEXT_TYPE__ NOT NULL CHECK (char_length("action") <= 32),
    "record_id" BIGINT NOT NULL CHECK ("record_id" >= 0),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_invoice_items" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "invoice_id" BIGINT NOT NULL CHECK ("invoice_id" >= 0),
    "source_type" __CITEXT_TYPE__ NOT NULL CHECK (char_length("source_type") <= 24),
    "source_id" BIGINT NOT NULL CHECK ("source_id" >= 0),
    "source_key" __CITEXT_TYPE__ NOT NULL CHECK (char_length("source_key") <= 64),
    "service_price_id" BIGINT CHECK ("service_price_id" >= 0),
    "drug_price_id" BIGINT CHECK ("drug_price_id" >= 0),
    "corrects_item_id" BIGINT CHECK ("corrects_item_id" >= 0),
    "quantity_micros" BIGINT NOT NULL CHECK ("quantity_micros" >= 0),
    "unit_price_micros" BIGINT NOT NULL CHECK ("unit_price_micros" >= 0),
    "amount_kobo" BIGINT NOT NULL CHECK ("amount_kobo" >= 0),
    "description" __CITEXT_TYPE__ NOT NULL CHECK (char_length("description") <= 191),
    "snapshot" JSONB NOT NULL,
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    "tariff_id" BIGINT CHECK ("tariff_id" >= 0),
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_invoice_posts" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "invoice_id" BIGINT NOT NULL CHECK ("invoice_id" >= 0),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_invoices" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "account_id" BIGINT NOT NULL CHECK ("account_id" >= 0),
    "encounter_id" BIGINT NOT NULL CHECK ("encounter_id" >= 0),
    "number" __CITEXT_TYPE__ NOT NULL CHECK (char_length("number") <= 64),
    "currency" __CITEXT_TYPE__ DEFAULT 'NGN' NOT NULL CHECK (char_length("currency") <= 3),
    "item_count" INTEGER NOT NULL CHECK ("item_count" >= 0),
    "total_kobo" BIGINT NOT NULL CHECK ("total_kobo" >= 0),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_performed_services" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "account_id" BIGINT NOT NULL CHECK ("account_id" >= 0),
    "encounter_id" BIGINT NOT NULL CHECK ("encounter_id" >= 0),
    "service_id" BIGINT NOT NULL CHECK ("service_id" >= 0),
    "quantity_micros" BIGINT NOT NULL CHECK ("quantity_micros" >= 0),
    "occurred_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reference" __CITEXT_TYPE__ NOT NULL CHECK (char_length("reference") <= 128),
    "reference_key" __CITEXT_TYPE__ NOT NULL CHECK (char_length("reference_key") <= 64),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "billing_receipts" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "account_id" BIGINT NOT NULL CHECK ("account_id" >= 0),
    "number" __CITEXT_TYPE__ NOT NULL CHECK (char_length("number") <= 64),
    "kind" __CITEXT_TYPE__ NOT NULL CHECK (char_length("kind") <= 16),
    "amount_kobo" BIGINT NOT NULL CHECK ("amount_kobo" >= 0),
    "currency" __CITEXT_TYPE__ DEFAULT 'NGN' NOT NULL CHECK (char_length("currency") <= 3),
    "method" __CITEXT_TYPE__ NOT NULL CHECK (char_length("method") <= 24),
    "reference" __CITEXT_TYPE__ CHECK (char_length("reference") <= 128),
    "reference_key" __CITEXT_TYPE__ CHECK (char_length("reference_key") <= 64),
    "payer_name" __CITEXT_TYPE__ NOT NULL CHECK (char_length("payer_name") <= 191),
    "payer_phone" __CITEXT_TYPE__ CHECK (char_length("payer_phone") <= 32),
    "paid_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "transaction_details" JSONB NOT NULL,
    "externally_confirmed" SMALLINT NOT NULL,
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "birth_patient_links" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "birth_id" BIGINT NOT NULL CHECK ("birth_id" >= 0),
    "child_patient_id" BIGINT NOT NULL CHECK ("child_patient_id" >= 0),
    "encounter_id" BIGINT NOT NULL CHECK ("encounter_id" >= 0),
    "verified_by" BIGINT NOT NULL CHECK ("verified_by" >= 0),
    "verified_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "births" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "delivery_id" BIGINT NOT NULL CHECK ("delivery_id" >= 0),
    "encounter_id" BIGINT NOT NULL CHECK ("encounter_id" >= 0),
    "birth_order" BIGINT NOT NULL CHECK ("birth_order" >= 0),
    "recorded_by" BIGINT NOT NULL CHECK ("recorded_by" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "cache" (
    "key" __CITEXT_TYPE__ NOT NULL CHECK (char_length("key") <= 255),
    "value" TEXT NOT NULL,
    "expiration" BIGINT NOT NULL,
    PRIMARY KEY ("key")
);

CREATE TABLE "cache_locks" (
    "key" __CITEXT_TYPE__ NOT NULL CHECK (char_length("key") <= 255),
    "owner" __CITEXT_TYPE__ NOT NULL CHECK (char_length("owner") <= 255),
    "expiration" BIGINT NOT NULL,
    PRIMARY KEY ("key")
);

CREATE TABLE "care_programs" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "patient_id" BIGINT NOT NULL CHECK ("patient_id" >= 0),
    "encounter_id" BIGINT NOT NULL CHECK ("encounter_id" >= 0),
    "type" __CITEXT_TYPE__ NOT NULL CHECK (char_length("type") <= 32),
    "status" __CITEXT_TYPE__ DEFAULT 'active' NOT NULL CHECK (char_length("status") <= 16),
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "started_by" BIGINT NOT NULL CHECK ("started_by" >= 0),
    "started_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "start_reason" TEXT NOT NULL,
    "completed_by" BIGINT CHECK ("completed_by" >= 0),
    "completed_encounter_id" BIGINT CHECK ("completed_encounter_id" >= 0),
    "completed_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "completion_reason" TEXT,
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("id")
);

CREATE TABLE "care_record_links" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "clinical_record_id" BIGINT NOT NULL CHECK ("clinical_record_id" >= 0),
    "care_program_id" BIGINT NOT NULL CHECK ("care_program_id" >= 0),
    "birth_id" BIGINT CHECK ("birth_id" >= 0),
    PRIMARY KEY ("id")
);

CREATE TABLE "clinical_entries" (
    "clinical_record_id" BIGINT NOT NULL CHECK ("clinical_record_id" >= 0),
    "section" __CITEXT_TYPE__ NOT NULL CHECK (char_length("section") <= 64),
    "clinical_template_version_id" BIGINT CHECK ("clinical_template_version_id" >= 0),
    "fields" JSONB NOT NULL,
    "content" TEXT,
    "related_record_id" BIGINT CHECK ("related_record_id" >= 0),
    PRIMARY KEY ("clinical_record_id")
);

CREATE TABLE "clinical_procedures" (
    "clinical_record_id" BIGINT NOT NULL CHECK ("clinical_record_id" >= 0),
    "name" __CITEXT_TYPE__ NOT NULL CHECK (char_length("name") <= 255),
    "code" __CITEXT_TYPE__ CHECK (char_length("code") <= 64),
    "remarks" TEXT,
    "findings" TEXT,
    "performed_by" BIGINT CHECK ("performed_by" >= 0),
    "performed_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "quoted_amount" DECIMAL(14,2),
    "currency" VARCHAR(3) COLLATE "C",
    PRIMARY KEY ("clinical_record_id")
);

CREATE TABLE "clinical_records" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "patient_id" BIGINT NOT NULL CHECK ("patient_id" >= 0),
    "encounter_id" BIGINT NOT NULL CHECK ("encounter_id" >= 0),
    "kind" VARCHAR(16) COLLATE "C" NOT NULL,
    "status" VARCHAR(16) COLLATE "C" DEFAULT 'draft' NOT NULL,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "authored_by" BIGINT NOT NULL CHECK ("authored_by" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "finalized_by" BIGINT CHECK ("finalized_by" >= 0),
    "finalized_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "amends_id" BIGINT CHECK ("amends_id" >= 0),
    "amendment_reason" TEXT,
    "void_reason" TEXT,
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("id")
);

CREATE TABLE "clinical_revisions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "clinical_record_id" BIGINT NOT NULL CHECK ("clinical_record_id" >= 0),
    "version" BIGINT NOT NULL CHECK ("version" >= 0),
    "operation" __CITEXT_TYPE__ NOT NULL CHECK (char_length("operation") <= 16),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "reason" TEXT,
    "snapshot" JSONB NOT NULL,
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "clinical_template_versions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "clinical_template_id" BIGINT NOT NULL CHECK ("clinical_template_id" >= 0),
    "version" BIGINT NOT NULL CHECK ("version" >= 0),
    "title" __CITEXT_TYPE__ NOT NULL CHECK (char_length("title") <= 160),
    "fields" JSONB NOT NULL,
    "published_by" BIGINT NOT NULL CHECK ("published_by" >= 0),
    "published_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "clinical_templates" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "code" VARCHAR(64) COLLATE "C" NOT NULL,
    "name" __CITEXT_TYPE__ NOT NULL CHECK (char_length("name") <= 160),
    "is_active" SMALLINT DEFAULT 1 NOT NULL,
    "created_by" BIGINT NOT NULL CHECK ("created_by" >= 0),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("id")
);

CREATE TABLE "departments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "code" __CITEXT_TYPE__ NOT NULL CHECK (char_length("code") <= 64),
    "name" __CITEXT_TYPE__ NOT NULL CHECK (char_length("name") <= 191),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("id")
);

CREATE TABLE "diagnoses" (
    "clinical_record_id" BIGINT NOT NULL CHECK ("clinical_record_id" >= 0),
    "description" TEXT NOT NULL,
    "code_system" __CITEXT_TYPE__ CHECK (char_length("code_system") <= 32),
    "code_system_version" __CITEXT_TYPE__ CHECK (char_length("code_system_version") <= 32),
    "code" __CITEXT_TYPE__ CHECK (char_length("code") <= 64),
    PRIMARY KEY ("clinical_record_id")
);

CREATE TABLE "doctor_assignments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "encounter_id" BIGINT NOT NULL CHECK ("encounter_id" >= 0),
    "doctor_id" BIGINT NOT NULL CHECK ("doctor_id" >= 0),
    "assigned_by" BIGINT NOT NULL CHECK ("assigned_by" >= 0),
    "assigned_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "accepted_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "ended_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "ended_by" BIGINT CHECK ("ended_by" >= 0),
    "end_reason" TEXT,
    "consultation_type" __CITEXT_TYPE__ CHECK (char_length("consultation_type") <= 64),
    "status" VARCHAR(16) COLLATE "C" DEFAULT 'assigned' NOT NULL,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "current_encounter_id" BIGINT GENERATED ALWAYS AS ((case when ("ended_at" is null) then "encounter_id" else NULL end)) STORED CHECK ("current_encounter_id" >= 0),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("id")
);

CREATE TABLE "document_exports" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "creator_id" BIGINT NOT NULL CHECK ("creator_id" >= 0),
    "kind" __CITEXT_TYPE__ NOT NULL CHECK (char_length("kind") <= 24),
    "format" __CITEXT_TYPE__ NOT NULL CHECK (char_length("format") <= 8),
    "bundle" TEXT NOT NULL,
    "byte_size" BIGINT NOT NULL CHECK ("byte_size" >= 0),
