    "schema_id" BIGINT NOT NULL CHECK ("schema_id" >= 0),
    "encounter_id" BIGINT NOT NULL CHECK ("encounter_id" >= 0),
    "previous_result_id" BIGINT CHECK ("previous_result_id" >= 0),
    "sequence" BIGINT NOT NULL CHECK ("sequence" >= 0),
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "status" __CITEXT_TYPE__ DEFAULT 'draft' NOT NULL CHECK (char_length("status") <= 16),
    "author_id" BIGINT NOT NULL CHECK ("author_id" >= 0),
    "fields" JSONB NOT NULL,
    "comment" TEXT,
    "reason" TEXT NOT NULL,
    "last_changed_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "submitted_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "verified_by" BIGINT CHECK ("verified_by" >= 0),
    "verified_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "released_by" BIGINT CHECK ("released_by" >= 0),
    "released_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "voided_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "working_item_id" BIGINT GENERATED ALWAYS AS ((case when ("status" in ('draft','submitted','verified')) then "item_id" else NULL end)) STORED CHECK ("working_item_id" >= 0),
    PRIMARY KEY ("id")
);

CREATE TABLE "investigation_revisions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
