    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "is_active" SMALLINT DEFAULT 1 NOT NULL,
    "next_sequence" INTEGER DEFAULT 1 NOT NULL CHECK ("next_sequence" >= 0),
    "next_due_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "stock_catalog_revisions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "catalog" __CITEXT_TYPE__ NOT NULL CHECK (char_length("catalog") <= 32),
    "record_id" BIGINT NOT NULL CHECK ("record_id" >= 0),
    "version" BIGINT NOT NULL CHECK ("version" >= 0),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" __CITEXT_TYPE__ NOT NULL CHECK (char_length("reason") <= 2000),
    "snapshot" JSONB NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "stock_invoice_receipts" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "operation_id" BIGINT NOT NULL CHECK ("operation_id" >= 0),
    "supplier_id" BIGINT NOT NULL CHECK ("supplier_id" >= 0),
    "invoice_key" __CITEXT_TYPE__ NOT NULL CHECK (char_length("invoice_key") <= 64),
    PRIMARY KEY ("id")
);

CREATE TABLE "stock_movements" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "movement_key" VARCHAR(64) COLLATE "C" NOT NULL,
    "drug_id" BIGINT NOT NULL CHECK ("drug_id" >= 0),
    "batch_id" BIGINT NOT NULL CHECK ("batch_id" >= 0),
    "store_id" BIGINT NOT NULL CHECK ("store_id" >= 0),
    "pack_id" BIGINT CHECK ("pack_id" >= 0),
    "kind" VARCHAR(32) COLLATE "C" NOT NULL,
    "quantity_micros" BIGINT NOT NULL,
    "unit_cost_micros" BIGINT,
    "currency" VARCHAR(3) COLLATE "C",
    "reference_type" VARCHAR(64) COLLATE "C" NOT NULL,
    "reference_id" VARCHAR(128) COLLATE "C" NOT NULL,
    "supplier_id" BIGINT CHECK ("supplier_id" >= 0),
    "reversal_of" BIGINT CHECK ("reversal_of" >= 0),
    "created_by" BIGINT NOT NULL CHECK ("created_by" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" VARCHAR(2000) COLLATE "C" NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "stock_operation_legs" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "line_id" BIGINT NOT NULL CHECK ("line_id" >= 0),
    "store_id" BIGINT NOT NULL CHECK ("store_id" >= 0),
    "movement_id" BIGINT NOT NULL CHECK ("movement_id" >= 0),
    PRIMARY KEY ("id")
);

CREATE TABLE "stock_operation_lines" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "operation_id" BIGINT NOT NULL CHECK ("operation_id" >= 0),
    "drug_id" BIGINT NOT NULL CHECK ("drug_id" >= 0),
    "drug_version" BIGINT NOT NULL CHECK ("drug_version" >= 0),
    "batch_id" BIGINT NOT NULL CHECK ("batch_id" >= 0),
    "pack_id" BIGINT CHECK ("pack_id" >= 0),
    "pack_count_micros" BIGINT,
    "quantity_micros" BIGINT NOT NULL,
    "unit_cost_micros" BIGINT,
    "source_balance_version" BIGINT CHECK ("source_balance_version" >= 0),
    "catalog_snapshot" JSONB NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "stock_operation_revisions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "operation_id" BIGINT NOT NULL CHECK ("operation_id" >= 0),
    "version" BIGINT NOT NULL CHECK ("version" >= 0),
    "action" __CITEXT_TYPE__ NOT NULL CHECK (char_length("action") <= 32),
    "actor_id" BIGINT NOT NULL CHECK ("actor_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" __CITEXT_TYPE__ NOT NULL CHECK (char_length("reason") <= 2000),
    "snapshot" JSONB NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "stock_operations" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "kind" VARCHAR(32) COLLATE "C" NOT NULL,
    "status" VARCHAR(16) COLLATE "C" DEFAULT 'draft' NOT NULL,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "source_store_id" BIGINT CHECK ("source_store_id" >= 0),
    "destination_store_id" BIGINT CHECK ("destination_store_id" >= 0),
    "source_store_version" BIGINT CHECK ("source_store_version" >= 0),
    "destination_store_version" BIGINT CHECK ("destination_store_version" >= 0),
    "supplier_id" BIGINT CHECK ("supplier_id" >= 0),
    "supplier_version" BIGINT CHECK ("supplier_version" >= 0),
    "invoice_number" VARCHAR(128) COLLATE "C",
    "currency" VARCHAR(3) COLLATE "C",
    "reference" VARCHAR(128) COLLATE "C" NOT NULL,
    "catalog_snapshot" JSONB NOT NULL,
    "prepared_by" BIGINT NOT NULL CHECK ("prepared_by" >= 0),
    "prepared_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reviewed_by" BIGINT CHECK ("reviewed_by" >= 0),
    "reviewed_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "posted_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "last_actor_id" BIGINT NOT NULL CHECK ("last_actor_id" >= 0),
    "last_changed_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" VARCHAR(2000) COLLATE "C" NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "stock_position_heads" (
    "store_id" BIGINT NOT NULL CHECK ("store_id" >= 0),
    "batch_id" BIGINT NOT NULL CHECK ("batch_id" >= 0),
    "quantity_micros" BIGINT DEFAULT 0 NOT NULL,
    "movement_count" BIGINT DEFAULT 0 NOT NULL CHECK ("movement_count" >= 0),
    "last_id" BIGINT CHECK ("last_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("store_id", "batch_id")
);

CREATE TABLE "stock_series_heads" (
    "drug_id" BIGINT NOT NULL CHECK ("drug_id" >= 0),
    "kind" VARCHAR(16) COLLATE "C" NOT NULL,
    "code" VARCHAR(64) COLLATE "C" NOT NULL,
    "version" BIGINT DEFAULT 0 NOT NULL CHECK ("version" >= 0),
    "last_id" BIGINT CHECK ("last_id" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "effective_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("drug_id", "kind", "code")
);

CREATE TABLE "stock_store_accesses" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "user_id" BIGINT NOT NULL CHECK ("user_id" >= 0),
    "store_id" BIGINT NOT NULL CHECK ("store_id" >= 0),
    "is_active" SMALLINT NOT NULL,
    "version" BIGINT NOT NULL CHECK ("version" >= 0),
    "changed_by" BIGINT NOT NULL CHECK ("changed_by" >= 0),
    "changed_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" __CITEXT_TYPE__ NOT NULL CHECK (char_length("reason") <= 2000),
    PRIMARY KEY ("id")
);

CREATE TABLE "stock_stores" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "code" VARCHAR(64) COLLATE "C" NOT NULL,
    "name" VARCHAR(191) COLLATE "C" NOT NULL,
    "department_id" BIGINT CHECK ("department_id" >= 0),
    "kind" VARCHAR(32) COLLATE "C" NOT NULL,
    "is_active" SMALLINT DEFAULT 1 NOT NULL,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "created_by" BIGINT NOT NULL CHECK ("created_by" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" VARCHAR(2000) COLLATE "C" NOT NULL,
    "updated_by" BIGINT NOT NULL CHECK ("updated_by" >= 0),
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "change_reason" VARCHAR(2000) COLLATE "C" NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "stock_units" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "code" VARCHAR(64) COLLATE "C" NOT NULL,
    "name" VARCHAR(191) COLLATE "C" NOT NULL,
    "created_by" BIGINT NOT NULL CHECK ("created_by" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" VARCHAR(2000) COLLATE "C" NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "suppliers" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "code" VARCHAR(64) COLLATE "C" NOT NULL,
    "name" VARCHAR(191) COLLATE "C" NOT NULL,
    "contact_name" VARCHAR(191) COLLATE "C",
    "phone" VARCHAR(32) COLLATE "C",
    "alternate_phone" VARCHAR(32) COLLATE "C",
    "email" VARCHAR(254) COLLATE "C",
    "address" VARCHAR(2000) COLLATE "C",
    "is_active" SMALLINT DEFAULT 1 NOT NULL,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "created_by" BIGINT NOT NULL CHECK ("created_by" >= 0),
    "recorded_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "reason" VARCHAR(2000) COLLATE "C" NOT NULL,
    "updated_by" BIGINT NOT NULL CHECK ("updated_by" >= 0),
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "change_reason" VARCHAR(2000) COLLATE "C" NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "user_roles" (
    "user_id" BIGINT NOT NULL CHECK ("user_id" >= 0),
    "role_id" BIGINT NOT NULL CHECK ("role_id" >= 0),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("user_id", "role_id")
);

CREATE TABLE "users" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "name" __CITEXT_TYPE__ NOT NULL CHECK (char_length("name") <= 255),
    "email" __CITEXT_TYPE__ CHECK (char_length("email") <= 255),
    "email_verified_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "password" __CITEXT_TYPE__ NOT NULL CHECK (char_length("password") <= 255),
    "remember_token" __CITEXT_TYPE__ CHECK (char_length("remember_token") <= 100),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "username" __CITEXT_TYPE__ NOT NULL CHECK (char_length("username") <= 64),
    "staff_code" __CITEXT_TYPE__ CHECK (char_length("staff_code") <= 64),
    "first_name" __CITEXT_TYPE__ NOT NULL CHECK (char_length("first_name") <= 64),
    "last_name" __CITEXT_TYPE__ NOT NULL CHECK (char_length("last_name") <= 64),
    "middle_name" __CITEXT_TYPE__ CHECK (char_length("middle_name") <= 64),
    "is_active" SMALLINT DEFAULT 1 NOT NULL,
    "last_login_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "department_id" BIGINT CHECK ("department_id" >= 0),
    PRIMARY KEY ("id")
);

CREATE TABLE "vital_signs" (
    "clinical_record_id" BIGINT NOT NULL CHECK ("clinical_record_id" >= 0),
    "observed_at" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    "temperature_c" DECIMAL(6,2),
    "systolic_mmhg" INTEGER CHECK ("systolic_mmhg" >= 0),
    "diastolic_mmhg" INTEGER CHECK ("diastolic_mmhg" >= 0),
    "weight_kg" DECIMAL(8,3),
    "height_m" DECIMAL(6,3),
    "blood_glucose" DECIMAL(10,3),
    "blood_glucose_unit" VARCHAR(16) COLLATE "C",
    "pulse_bpm" DECIMAL(7,2),
    "respiratory_rate" DECIMAL(7,2),
    "spo2_percent" DECIMAL(5,2),
    "fetal_heart_rate" DECIMAL(7,2),
    "urinalysis" TEXT,
    "comment" TEXT,
    PRIMARY KEY ("clinical_record_id")
);

CREATE TABLE "wards" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CHECK ("id" >= 0),
    "code" __CITEXT_TYPE__ NOT NULL CHECK (char_length("code") <= 64),
    "name" __CITEXT_TYPE__ NOT NULL CHECK (char_length("name") <= 191),
    "type" __CITEXT_TYPE__ CHECK (char_length("type") <= 64),
    "daily_rate" DECIMAL(14,2),
    "is_active" SMALLINT DEFAULT 1 NOT NULL,
    "version" BIGINT DEFAULT 1 NOT NULL CHECK ("version" >= 0),
    "created_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    "updated_at" TIMESTAMP(6) WITHOUT TIME ZONE,
    PRIMARY KEY ("id")
);

