CREATE VIEW "current_bed_occupancies" AS select distinct "bed_allocations"."bed_id" AS "bed_id","bed_allocations"."admission_id" AS "admission_id","bed_allocations"."id" AS "allocation_id","bed_allocations"."created_at" AS "created_at","bed_allocations"."updated_at" AS "updated_at" from "bed_allocations" where ("bed_allocations"."released_at" is null);

CREATE VIEW "stock_balances" AS select "stock_movements"."store_id" AS "store_id","stock_movements"."batch_id" AS "batch_id","stock_movements"."drug_id" AS "drug_id",sum("stock_movements"."quantity_micros") AS "quantity_micros",count(0) AS "movement_count",max("stock_movements"."id") AS "last_movement_id",max("stock_movements"."recorded_at") AS "last_changed_at" from "stock_movements" group by "stock_movements"."store_id","stock_movements"."batch_id","stock_movements"."drug_id";

CREATE OR REPLACE FUNCTION "guard_accommodation_exit_binding"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.status NOT IN ('ready','requires_review')
            OR (NEW.status = 'ready' AND (NEW.total_kobo IS NULL OR NEW.total_kobo NOT BETWEEN 0 AND 99999999999))
            OR (NEW.status = 'requires_review' AND NEW.total_kobo IS NOT NULL)
            OR NOT EXISTS (SELECT 1 FROM admissions a WHERE a.id = NEW.admission_id AND a.status = 'discharged'
                AND a.discharged_by = NEW.actor_id AND a.discharged_at = NEW.recorded_at) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Retained pricing integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_accommodation_exit_binding" BEFORE INSERT ON "accommodation_assessments" FOR EACH ROW EXECUTE FUNCTION "guard_accommodation_exit_binding"();

CREATE OR REPLACE FUNCTION "guard_accommodation_assessments_retain_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF 1 = 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Retained pricing integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_accommodation_assessments_retain_update" BEFORE UPDATE ON "accommodation_assessments" FOR EACH ROW EXECUTE FUNCTION "guard_accommodation_assessments_retain_update"();

