CREATE OR REPLACE FUNCTION "guard_admission_exit_binding"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.exit_type NOT IN ('discharge','referral','dama')
            OR NOT EXISTS (SELECT 1 FROM admissions a WHERE a.id = NEW.admission_id AND a.status = 'discharge_authorized'
                AND a.authorized_by = NEW.actor_id AND a.authorized_at = NEW.recorded_at) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Retained pricing integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_admission_exit_binding" BEFORE INSERT ON "admission_exit_types" FOR EACH ROW EXECUTE FUNCTION "guard_admission_exit_binding"();

