CREATE OR REPLACE FUNCTION "guard_admission_revisions_validate"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.workflow_version BETWEEN 1 AND 4294967294
            AND NEW.operation IN ('admitted', 'allocated', 'transferred', 'released', 'discharge_authorized', 'discharged')
            AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000 AND ((NEW.snapshot #>> '{id}'))::BIGINT = NEW.admission_id
            AND ((NEW.snapshot #>> '{workflow_version}'))::BIGINT = NEW.workflow_version
            AND NEW.workflow_version = COALESCE((SELECT MAX(r.workflow_version) FROM admission_revisions r
                WHERE r.admission_id = NEW.admission_id), 0) + 1) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid admission history snapshot.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_admission_revisions_validate" BEFORE INSERT ON "admission_revisions" FOR EACH ROW EXECUTE FUNCTION "guard_admission_revisions_validate"();

CREATE OR REPLACE FUNCTION "guard_admission_revisions_no_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF 1 = 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Admission history is append-only.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_admission_revisions_no_update" BEFORE UPDATE ON "admission_revisions" FOR EACH ROW EXECUTE FUNCTION "guard_admission_revisions_no_update"();

