CREATE OR REPLACE FUNCTION "guard_admissions_lock_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
DECLARE locked_id BIGINT ;
BEGIN
                SELECT id INTO locked_id FROM patients WHERE id = NEW.patient_id FOR UPDATE;
                SELECT id INTO locked_id FROM encounters WHERE id = NEW.encounter_id FOR UPDATE; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_admissions_lock_insert" BEFORE INSERT ON "admissions" FOR EACH ROW EXECUTE FUNCTION "guard_admissions_lock_insert"();

CREATE OR REPLACE FUNCTION "guard_admissions_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version BETWEEN 1 AND 4294967294 AND NEW.status IN ('admitted', 'discharge_authorized', 'discharged')
            AND EXISTS (SELECT 1 FROM encounters e WHERE e.id = NEW.encounter_id AND e.patient_id = NEW.patient_id
                AND e.status IN ('open', 'in_progress') AND NEW.admitted_at >= e.opened_at FOR UPDATE)
            AND (NEW.discharge_summary IS NULL OR CHAR_LENGTH(NEW.discharge_summary) <= 20000)
            AND ((NEW.status = 'admitted' AND NEW.authorized_at IS NULL AND NEW.authorized_by IS NULL
                AND NEW.discharged_at IS NULL AND NEW.discharged_by IS NULL AND NEW.discharge_reason IS NULL AND NEW.discharge_summary IS NULL)
            OR (NEW.status IN ('discharge_authorized', 'discharged') AND NEW.authorized_at IS NOT NULL AND NEW.authorized_by IS NOT NULL
                AND NEW.authorized_at >= NEW.admitted_at AND CHAR_LENGTH(trim(NEW.discharge_reason)) BETWEEN 5 AND 2000
                AND ((NEW.status = 'discharge_authorized' AND NEW.discharged_at IS NULL AND NEW.discharged_by IS NULL)
                    OR (NEW.status = 'discharged' AND NEW.discharged_at IS NOT NULL AND NEW.discharged_by IS NOT NULL
                        AND NEW.discharged_at >= NEW.authorized_at))))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid admission storage record.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_admissions_validate_insert" BEFORE INSERT ON "admissions" FOR EACH ROW EXECUTE FUNCTION "guard_admissions_validate_insert"();

CREATE OR REPLACE FUNCTION "guard_admissions_start_admitted"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.status <> 'admitted' OR NEW.version <> 1
            OR NOT EXISTS (SELECT 1 FROM patients p WHERE p.id = NEW.patient_id AND p.access_status = 'active' FOR UPDATE)
            OR EXISTS (SELECT 1 FROM admissions a WHERE a.patient_id = NEW.patient_id
                AND (a.status <> 'discharged' OR a.discharged_at > NEW.admitted_at) FOR SHARE) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Admissions must start after earlier inpatient episodes ended against an active identity.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_admissions_start_admitted" BEFORE INSERT ON "admissions" FOR EACH ROW EXECUTE FUNCTION "guard_admissions_start_admitted"();

CREATE OR REPLACE FUNCTION "guard_admissions_lock_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
DECLARE locked_id BIGINT ;
BEGIN
