CREATE OR REPLACE FUNCTION "guard_admissions_validate_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version BETWEEN 1 AND 4294967294 AND NEW.status IN ('admitted', 'discharge_authorized', 'discharged')
            AND EXISTS (SELECT 1 FROM encounters e WHERE e.id = NEW.encounter_id AND e.patient_id = NEW.patient_id
                AND e.status IN ('open', 'in_progress') AND NEW.admitted_at >= e.opened_at FOR UPDATE)
            AND (NEW.discharge_summary IS NULL OR CHAR_LENGTH(NEW.discharge_summary) <= 20000)
            AND ((NEW.status = 'admitted' AND NEW.authorized_at IS NULL AND NEW.authorized_by IS NULL
                AND NEW.discharged_at IS NULL AND NEW.discharged_by IS NULL AND NEW.discharge_reason IS NULL AND NEW.discharge_summary IS NULL)
            OR (NEW.status IN ('discharge_authorized', 'discharged') AND NEW.authorized_at IS NOT NULL AND NEW.authorized_by IS NOT NULL
                AND NEW.authorized_at >= NEW.admitted_at AND CHAR_LENGTH(trim(NEW.discharge_reason)) BETWEEN 5 AND 2000
                AND ((NEW.status = 'discharge_authorized' AND NEW.discharged_at IS NULL AND NEW.discharged_by IS NULL)
                    OR (NEW.status = 'discharged' AND NEW.discharged_at IS NOT NULL AND NEW.discharged_by IS NOT NULL
                        AND NEW.discharged_at >= NEW.authorized_at))))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid admission storage record.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_admissions_validate_update" BEFORE UPDATE ON "admissions" FOR EACH ROW EXECUTE FUNCTION "guard_admissions_validate_update"();

CREATE OR REPLACE FUNCTION "guard_admissions_preserve_lifecycle"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.id <> OLD.id OR NEW.patient_id <> OLD.patient_id
            OR NEW.encounter_id <> OLD.encounter_id OR NEW.admitted_by <> OLD.admitted_by OR NOT (((NEW.admitted_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.admitted_at)::TEXT COLLATE "C"))
            OR NOT (((NEW.created_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_at)::TEXT COLLATE "C")) OR NEW.version <> OLD.version + 1
            OR NOT ((OLD.status = 'admitted' AND NEW.status = 'discharge_authorized') OR (OLD.status = 'discharge_authorized' AND NEW.status = 'discharged'))
            OR (OLD.status = 'discharge_authorized' AND (NOT (((NEW.authorized_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.authorized_at)::TEXT COLLATE "C")) OR NOT (((NEW.authorized_by)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.authorized_by)::TEXT COLLATE "C")) OR NOT (((NEW.discharge_reason)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.discharge_reason)::TEXT COLLATE "C")) OR NOT (((NEW.discharge_summary)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.discharge_summary)::TEXT COLLATE "C")))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Admission identity, authorization, version or transition is invalid.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_admissions_preserve_lifecycle" BEFORE UPDATE ON "admissions" FOR EACH ROW EXECUTE FUNCTION "guard_admissions_preserve_lifecycle"();

CREATE OR REPLACE FUNCTION "guard_admissions_authorization_time"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF OLD.status = 'admitted' AND EXISTS
            (SELECT 1 FROM bed_allocations a WHERE a.admission_id = OLD.id
                AND (a.assigned_at > NEW.authorized_at OR a.released_at > NEW.authorized_at) FOR UPDATE) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Authorization cannot precede recorded allocation activity.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g004_admissions_authorization_time" BEFORE UPDATE ON "admissions" FOR EACH ROW EXECUTE FUNCTION "guard_admissions_authorization_time"();

CREATE OR REPLACE FUNCTION "guard_admissions_discharge_empty"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.status = 'discharged' AND EXISTS
            (SELECT 1 FROM bed_allocations a WHERE a.admission_id = OLD.id AND (a.released_at IS NULL OR a.released_at > NEW.discharged_at) FOR UPDATE) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Discharge requires all allocations to be released by the discharge time.'; END IF; RETURN NEW; END;
$guard$;

