CREATE OR REPLACE FUNCTION "guard_allocation_rate_binding"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.daily_rate_kobo IS NOT NULL AND NEW.daily_rate_kobo NOT BETWEEN 0 AND 99999999999999)
            OR NEW.source NOT IN ('bed','ward','missing') OR NOT EXISTS (SELECT 1 FROM bed_allocations a WHERE a.id = NEW.allocation_id
                AND a.assigned_by = NEW.actor_id AND a.assigned_at = NEW.recorded_at) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Retained pricing integrity violation'; END IF; RETURN NEW; END;
$guard$;

