CREATE OR REPLACE FUNCTION "guard_appointment_follow_ups_validate"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.appointment_id = NEW.previous_appointment_id OR NOT EXISTS
                (SELECT 1 FROM appointments child JOIN appointments parent ON parent.id = NEW.previous_appointment_id
                WHERE child.id = NEW.appointment_id AND child.version = 1 AND child.status = 'booked'
                    AND child.booked_by = NEW.created_by AND parent.status = 'attended'
                    AND parent.patient_id IS NOT NULL AND parent.patient_id = child.patient_id AND child.starts_at > parent.starts_at) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A follow-up requires a new booking after an attended booking for the same patient.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_appointment_follow_ups_validate" BEFORE INSERT ON "appointment_follow_ups" FOR EACH ROW EXECUTE FUNCTION "guard_appointment_follow_ups_validate"();

