CREATE OR REPLACE FUNCTION "guard_appointment_revisions_validate"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.version > 0 AND NEW.operation IN ('created', 'updated', 'rescheduled', 'confirmed', 'cancelled', 'no_show', 'attended')
                AND ((NEW.operation = 'created' AND NEW.version = 1 AND NEW.reason IS NULL)
                    OR (NEW.operation <> 'created' AND NEW.version > 1 AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000))
                AND ((NEW.snapshot #>> '{id}'))::BIGINT = NEW.appointment_id AND ((NEW.snapshot #>> '{version}'))::BIGINT = NEW.version
                AND EXISTS (SELECT 1 FROM appointments a WHERE a.id = NEW.appointment_id AND a.version = NEW.version)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid appointment history snapshot.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_appointment_revisions_validate" BEFORE INSERT ON "appointment_revisions" FOR EACH ROW EXECUTE FUNCTION "guard_appointment_revisions_validate"();

