CREATE OR REPLACE FUNCTION "guard_appointments_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (CHAR_LENGTH(trim(NEW.first_name)) BETWEEN 1 AND 64
            AND CHAR_LENGTH(trim(NEW.last_name)) BETWEEN 1 AND 64 AND octet_length(trim(NEW.phone)) BETWEEN 1 AND 32
            AND CHAR_LENGTH(trim(NEW.booking_channel)) BETWEEN 1 AND 64 AND CHAR_LENGTH(trim(NEW.visit_type)) BETWEEN 1 AND 64
            AND NEW.version > 0 AND NEW.status IN ('booked', 'confirmed', 'attended', 'cancelled', 'no_show')
            AND (NEW.ends_at IS NULL OR NEW.ends_at > NEW.starts_at)
            AND (NEW.status <> 'attended' OR NEW.patient_id IS NOT NULL)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid visit record.'; END IF; RETURN NEW; END;
$guard$;

