CREATE OR REPLACE FUNCTION "guard_appointments_preserve_lifecycle"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.id <> OLD.id OR NEW.booked_by <> OLD.booked_by OR NOT (((NEW.created_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_at)::TEXT COLLATE "C"))
            OR NEW.version <> OLD.version + 1 OR OLD.status NOT IN ('booked', 'confirmed')
            OR (OLD.patient_id IS NOT NULL AND NOT (((NEW.patient_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.patient_id)::TEXT COLLATE "C")))
            OR NOT (NEW.status = OLD.status
                OR (OLD.status = 'booked' AND NEW.status IN ('confirmed', 'attended', 'cancelled', 'no_show'))
                OR (OLD.status = 'confirmed' AND NEW.status IN ('attended', 'cancelled', 'no_show'))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Appointment identity, version or transition is invalid.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_appointments_preserve_lifecycle" BEFORE UPDATE ON "appointments" FOR EACH ROW EXECUTE FUNCTION "guard_appointments_preserve_lifecycle"();

