            AND CHAR_LENGTH(trim(NEW.last_name)) BETWEEN 1 AND 64 AND octet_length(trim(NEW.phone)) BETWEEN 1 AND 32
            AND CHAR_LENGTH(trim(NEW.booking_channel)) BETWEEN 1 AND 64 AND CHAR_LENGTH(trim(NEW.visit_type)) BETWEEN 1 AND 64
            AND NEW.version > 0 AND NEW.status IN ('booked', 'confirmed', 'attended', 'cancelled', 'no_show')
            AND (NEW.ends_at IS NULL OR NEW.ends_at > NEW.starts_at)
