BEGIN IF EXISTS (SELECT 1 FROM appointment_follow_ups f JOIN appointments parent ON parent.id = f.previous_appointment_id
                WHERE f.appointment_id = OLD.id AND NEW.starts_at <= parent.starts_at) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A follow-up cannot precede its original attended booking.'; END IF; RETURN NEW; END;
$guard$;

