CREATE OR REPLACE FUNCTION "guard_bed_allocations_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version BETWEEN 1 AND 4294967294 AND CHAR_LENGTH(trim(NEW.assignment_reason)) BETWEEN 5 AND 2000
            AND EXISTS (SELECT 1 FROM admissions a JOIN encounters e ON e.id = a.encounter_id
                WHERE a.id = NEW.admission_id AND a.status IN ('admitted', 'discharge_authorized')
                AND e.status IN ('open', 'in_progress') AND NEW.assigned_at >= a.admitted_at FOR UPDATE)
            AND ((NEW.released_at IS NULL AND NEW.released_by IS NULL AND NEW.release_reason IS NULL)
                OR (NEW.released_at IS NOT NULL AND NEW.released_at >= NEW.assigned_at AND NEW.released_by IS NOT NULL
                    AND CHAR_LENGTH(trim(NEW.release_reason)) BETWEEN 5 AND 2000))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid admission storage record.'; END IF; RETURN NEW; END;
$guard$;

