CREATE OR REPLACE FUNCTION "guard_allocations_start_current"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.version <> 1 OR NEW.released_at IS NOT NULL
            OR NOT EXISTS (SELECT 1 FROM beds b JOIN wards w ON w.id = b.ward_id WHERE b.id = NEW.bed_id AND b.is_active = 1 AND w.is_active = 1 FOR UPDATE)
            OR EXISTS (SELECT 1 FROM bed_allocations a WHERE (a.bed_id = NEW.bed_id OR a.admission_id = NEW.admission_id)
                AND (a.released_at IS NULL OR a.released_at > NEW.assigned_at) FOR SHARE) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Allocate an active available bed after earlier allocations ended.'; END IF; RETURN NEW; END;
$guard$;

