                IF NEW.id <> OLD.id OR NEW.bed_id <> OLD.bed_id
            OR NEW.admission_id <> OLD.admission_id OR NEW.assigned_by <> OLD.assigned_by OR NOT (((NEW.assigned_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.assigned_at)::TEXT COLLATE "C"))
            OR NOT (((NEW.assignment_reason)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.assignment_reason)::TEXT COLLATE "C")) OR NOT (((NEW.created_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_at)::TEXT COLLATE "C"))
            OR OLD.released_at IS NOT NULL OR NEW.released_at IS NULL OR NEW.version <> OLD.version + 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Allocation history can only be released once.'; END IF; RETURN NEW; END;
