BEGIN
                IF NOT (((NEW.label)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.label)::TEXT COLLATE "C"))
            AND EXISTS (SELECT 1 FROM bed_allocations a WHERE a.bed_id = OLD.id FOR UPDATE) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Used bed labels cannot be rewritten.'; END IF; RETURN NEW; END;
$guard$;

