CREATE OR REPLACE FUNCTION "guard_billing_release_account"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NOT EXISTS (SELECT 1 FROM billing_allocations a JOIN billing_invoices i ON i.id = a.invoice_id
            JOIN billing_change_reviews v ON v.id = NEW.review_id JOIN billing_changes c ON c.id = v.change_id JOIN billing_invoice_items l ON l.id = c.item_id
            WHERE a.id = NEW.allocation_id AND v.decision = 'approved' AND c.kind = 'credit' AND l.invoice_id = i.id AND c.account_id = i.account_id) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Billing integrity violation'; END IF; RETURN NEW; END;
