CREATE OR REPLACE FUNCTION "guard_billing_change_reviewer"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.decision NOT IN ('approved','rejected')
            OR NOT EXISTS (SELECT 1 FROM billing_changes c WHERE c.id = NEW.change_id AND c.actor_id <> NEW.actor_id AND c.recorded_at <= NEW.recorded_at) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Billing integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_billing_change_reviewer" BEFORE INSERT ON "billing_change_reviews" FOR EACH ROW EXECUTE FUNCTION "guard_billing_change_reviewer"();

CREATE OR REPLACE FUNCTION "guard_billing_payout_confirmation"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NOT EXISTS (SELECT 1 FROM billing_changes c WHERE c.id = NEW.change_id
            AND ((c.kind = 'refund' AND NEW.decision = 'approved' AND NEW.payout_confirmed = 1 AND NEW.payout_key IS NOT NULL
                AND NEW.payout_reference IS NOT NULL AND NEW.payout_at IS NOT NULL AND NEW.payout_at <= NEW.recorded_at
                AND NEW.payout_method IN ('cash','bank_transfer','pos','other') AND NEW.payee_name IS NOT NULL AND NEW.payout_details IS NOT NULL)
            OR ((c.kind <> 'refund' OR NEW.decision <> 'approved') AND NEW.payout_confirmed = 0
                AND NEW.payout_key IS NULL AND NEW.payout_reference IS NULL AND NEW.payout_at IS NULL
                AND NEW.payout_method IS NULL AND NEW.payee_name IS NULL AND NEW.payout_details IS NULL))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Billing workflow integrity violation'; END IF; RETURN NEW; END;
$guard$;

