CREATE OR REPLACE FUNCTION "guard_billing_change_target"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF ((NEW.kind = 'credit' AND NEW.receipt_id IS NULL AND NEW.item_id IS NOT NULL
            AND EXISTS (SELECT 1 FROM billing_invoice_items l JOIN billing_invoices i ON i.id = l.invoice_id WHERE l.id = NEW.item_id AND i.account_id = NEW.account_id))
            OR (NEW.kind = 'refund' AND NEW.item_id IS NULL AND NEW.replacement_quantity_micros IS NULL AND NEW.receipt_id IS NOT NULL
            AND EXISTS (SELECT 1 FROM billing_receipts r WHERE r.id = NEW.receipt_id AND r.account_id = NEW.account_id))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Billing integrity violation'; END IF; RETURN NEW; END;
$guard$;

