CREATE OR REPLACE FUNCTION "guard_billing_event_sequence"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.version NOT BETWEEN 1 AND 4294967293 OR (NEW.version > 1 AND NOT EXISTS (
            SELECT 1 FROM billing_events e WHERE e.account_id = NEW.account_id AND e.version = NEW.version - 1 AND e.recorded_at <= NEW.recorded_at)) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Billing workflow integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_billing_event_sequence" BEFORE INSERT ON "billing_events" FOR EACH ROW EXECUTE FUNCTION "guard_billing_event_sequence"();

CREATE OR REPLACE FUNCTION "guard_billing_event_binding"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NOT ((NEW.action='performed' AND EXISTS (SELECT 1 FROM billing_performed_services r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='invoice' AND EXISTS (SELECT 1 FROM billing_invoices r JOIN billing_invoice_posts p ON p.invoice_id=r.id WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='receipt' AND EXISTS (SELECT 1 FROM billing_receipts r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='allocate' AND EXISTS (SELECT 1 FROM billing_allocations r JOIN billing_receipts p ON p.id=r.receipt_id WHERE r.id=NEW.record_id AND p.account_id=NEW.account_id)) OR (NEW.action='credit-request' AND EXISTS (SELECT 1 FROM billing_changes r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id AND r.kind='credit')) OR (NEW.action='refund-request' AND EXISTS (SELECT 1 FROM billing_changes r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id AND r.kind='refund')) OR (NEW.action='approve' AND EXISTS (SELECT 1 FROM billing_change_reviews r JOIN billing_changes c ON c.id=r.change_id WHERE r.id=NEW.record_id AND c.account_id=NEW.account_id AND r.decision='approved')) OR (NEW.action='reject' AND EXISTS (SELECT 1 FROM billing_change_reviews r JOIN billing_changes c ON c.id=r.change_id WHERE r.id=NEW.record_id AND c.account_id=NEW.account_id AND r.decision='rejected')) OR (NEW.action='hmo.coverage-create' AND EXISTS (SELECT 1 FROM hmo_coverages r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='hmo.preauth-create' AND EXISTS (SELECT 1 FROM hmo_preauthorizations r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='hmo.coverage-revoke' AND EXISTS (SELECT 1 FROM hmo_revocations r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='hmo.preauth-revoke' AND EXISTS (SELECT 1 FROM hmo_revocations r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='hmo.claim-submit' AND EXISTS (SELECT 1 FROM hmo_claims r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='hmo.claim-resubmit' AND EXISTS (SELECT 1 FROM hmo_claims r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='hmo.allocation-record' AND EXISTS (SELECT 1 FROM hmo_allocations r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='hmo.invoice' AND EXISTS (SELECT 1 FROM billing_invoices r JOIN hmo_invoice_links l ON l.invoice_id=r.id WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='hmo.decision-record' AND EXISTS (SELECT 1 FROM hmo_decisions d JOIN hmo_claims c ON c.id=d.claim_id WHERE d.id=NEW.record_id AND c.account_id=NEW.account_id)) OR (NEW.action='hmo.decision-review' AND EXISTS (SELECT 1 FROM hmo_reviews r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)) OR (NEW.action='hmo.allocation-review' AND EXISTS (SELECT 1 FROM hmo_reviews r WHERE r.id=NEW.record_id AND r.account_id=NEW.account_id)))
                THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'HMO integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_billing_event_binding" BEFORE INSERT ON "billing_events" FOR EACH ROW EXECUTE FUNCTION "guard_billing_event_binding"();

