CREATE OR REPLACE FUNCTION "guard_billing_receipt_method"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.kind NOT IN ('deposit','payment') OR NEW.method NOT IN ('cash','bank_transfer','pos','other')
            OR (NEW.method <> 'cash' AND (NEW.reference IS NULL OR NEW.reference_key IS NULL OR NEW.externally_confirmed <> 1))
            OR (NEW.method = 'cash' AND NEW.externally_confirmed <> 0) OR NEW.paid_at > NEW.recorded_at THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Billing integrity violation'; END IF; RETURN NEW; END;
$guard$;

