CREATE OR REPLACE FUNCTION "guard_birth_link_identity"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000
            AND EXISTS (SELECT 1 FROM births b JOIN care_programs p ON p.id = b.delivery_id
                JOIN patients child ON child.id = NEW.child_patient_id
                JOIN encounters e ON e.id = NEW.encounter_id
                WHERE b.id = NEW.birth_id AND p.status = 'active' AND p.patient_id <> NEW.child_patient_id
                AND child.access_status = 'active' AND e.patient_id = p.patient_id AND e.status IN ('open','in_progress')
                AND NEW.verified_at >= b.recorded_at AND NEW.verified_at >= e.opened_at)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid or immutable care-program record.'; END IF; RETURN NEW; END;
$guard$;

