CREATE OR REPLACE FUNCTION "guard_births_delivery"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.birth_order BETWEEN 1 AND 4294967294
            AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000 AND EXISTS
            (SELECT 1 FROM care_programs p JOIN encounters e ON e.id = NEW.encounter_id WHERE p.id = NEW.delivery_id
                AND p.type = 'delivery' AND p.status = 'active' AND e.patient_id = p.patient_id AND e.status IN ('open','in_progress')
                AND NEW.recorded_at >= p.started_at AND NEW.recorded_at >= e.opened_at)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid or immutable care-program record.'; END IF; RETURN NEW; END;
$guard$;

