CREATE OR REPLACE FUNCTION "guard_care_programs_start"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.type IN ('antenatal','postnatal','family_planning','delivery','immunization')
            AND NEW.status = 'active' AND NEW.version = 1 AND NEW.completed_at IS NULL AND NEW.completed_by IS NULL AND NEW.completed_encounter_id IS NULL
            AND NEW.completion_reason IS NULL AND CHAR_LENGTH(trim(NEW.start_reason)) BETWEEN 5 AND 2000
            AND EXISTS (SELECT 1 FROM encounters e JOIN patients p ON p.id = e.patient_id WHERE e.id = NEW.encounter_id
                AND e.patient_id = NEW.patient_id AND e.status IN ('open','in_progress') AND p.access_status = 'active'
                AND NEW.started_at >= e.opened_at)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid or immutable care-program record.'; END IF; RETURN NEW; END;
$guard$;

