BEGIN IF NOT EXISTS (SELECT 1 FROM clinical_records r WHERE r.id = NEW.clinical_record_id AND r.kind = 'entry' AND r.status = 'draft' FOR UPDATE) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Only matching draft clinical content can be written.'; END IF; RETURN NEW; END;
$guard$;

