CREATE OR REPLACE FUNCTION "guard_clinical_entries_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (CHAR_LENGTH(trim(NEW.section)) BETWEEN 1 AND 64 AND upper(jsonb_typeof(NEW.fields)) = 'OBJECT'
            AND (NEW.related_record_id IS NULL OR EXISTS (SELECT 1 FROM clinical_records a JOIN clinical_records b
                ON a.encounter_id = b.encounter_id AND a.patient_id = b.patient_id
                WHERE a.id = NEW.clinical_record_id AND b.id = NEW.related_record_id AND a.id <> b.id))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid clinical storage value.'; END IF; RETURN NEW; END;
$guard$;

