CREATE OR REPLACE FUNCTION "guard_clinical_procedures_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (CHAR_LENGTH(trim(NEW.name)) BETWEEN 1 AND 255
            AND ((NEW.performed_by IS NULL AND NEW.performed_at IS NULL) OR (NEW.performed_by IS NOT NULL AND NEW.performed_at IS NOT NULL))
            AND ((NEW.quoted_amount IS NULL AND NEW.currency IS NULL) OR (NEW.quoted_amount >= 0 AND NEW.currency ~ '^[A-Z]{3}$'))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid clinical storage value.'; END IF; RETURN NEW; END;
$guard$;

