                SELECT id INTO locked_id FROM encounters WHERE id = NEW.encounter_id FOR UPDATE; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_clinical_records_lock_insert" BEFORE INSERT ON "clinical_records" FOR EACH ROW EXECUTE FUNCTION "guard_clinical_records_lock_insert"();

CREATE OR REPLACE FUNCTION "guard_clinical_records_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.status = 'draft' AND NEW.version = 1 AND NEW.finalized_by IS NULL AND NEW.finalized_at IS NULL
                AND NEW.void_reason IS NULL AND NEW.kind IN ('vitals', 'entry', 'diagnosis', 'procedure', 'prescription')
                AND EXISTS (SELECT 1 FROM patients p WHERE p.id = NEW.patient_id AND p.access_status = 'active')
                AND EXISTS (SELECT 1 FROM encounters e WHERE e.id = NEW.encounter_id AND e.patient_id = NEW.patient_id
                    AND NEW.recorded_at >= e.opened_at AND (e.status IN ('open', 'in_progress') OR (e.status = 'closed' AND NEW.amends_id IS NOT NULL)))
                AND ((NEW.amends_id IS NULL AND NEW.amendment_reason IS NULL)
                    OR (CHAR_LENGTH(trim(NEW.amendment_reason)) BETWEEN 5 AND 2000 AND EXISTS
                        (SELECT 1 FROM clinical_records r WHERE r.id = NEW.amends_id AND r.status IN ('signed', 'voided')
                            AND r.encounter_id = NEW.encounter_id AND r.patient_id = NEW.patient_id AND r.kind = NEW.kind
                            AND NEW.recorded_at >= r.finalized_at)))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid clinical draft or amendment.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_clinical_records_validate_insert" BEFORE INSERT ON "clinical_records" FOR EACH ROW EXECUTE FUNCTION "guard_clinical_records_validate_insert"();

CREATE OR REPLACE FUNCTION "guard_clinical_records_lock_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
DECLARE locked_id BIGINT ;
BEGIN
                SELECT id INTO locked_id FROM encounters WHERE id = NEW.encounter_id FOR UPDATE; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_clinical_records_lock_update" BEFORE UPDATE ON "clinical_records" FOR EACH ROW EXECUTE FUNCTION "guard_clinical_records_lock_update"();

CREATE OR REPLACE FUNCTION "guard_clinical_records_validate_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.kind IN ('vitals', 'entry', 'diagnosis', 'procedure', 'prescription')
            AND NEW.version > 0 AND NEW.recorded_at IS NOT NULL
            AND EXISTS (SELECT 1 FROM encounters e WHERE e.id = NEW.encounter_id AND e.patient_id = NEW.patient_id
                AND NEW.recorded_at >= e.opened_at AND e.status <> 'cancelled')
            AND ((NEW.amends_id IS NULL AND NEW.amendment_reason IS NULL)
                OR (CHAR_LENGTH(trim(NEW.amendment_reason)) BETWEEN 5 AND 2000))
            AND ((NEW.status = 'draft' AND NEW.finalized_by IS NULL AND NEW.finalized_at IS NULL AND NEW.void_reason IS NULL)
                OR (NEW.status = 'signed' AND NEW.finalized_by IS NOT NULL AND NEW.finalized_at >= NEW.recorded_at AND NEW.void_reason IS NULL)
                OR (NEW.status = 'voided' AND NEW.finalized_by IS NOT NULL AND NEW.finalized_at >= NEW.recorded_at
                    AND CHAR_LENGTH(trim(NEW.void_reason)) BETWEEN 5 AND 2000))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid clinical storage value.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_clinical_records_validate_update" BEFORE UPDATE ON "clinical_records" FOR EACH ROW EXECUTE FUNCTION "guard_clinical_records_validate_update"();

CREATE OR REPLACE FUNCTION "guard_clinical_records_preserve_history"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF OLD.status <> 'draft' OR NEW.version <> OLD.version + 1 OR NOT (((NEW.id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.id)::TEXT COLLATE "C")) OR NOT (((NEW.patient_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.patient_id)::TEXT COLLATE "C")) OR NOT (((NEW.encounter_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.encounter_id)::TEXT COLLATE "C")) OR NOT (((NEW.kind)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.kind)::TEXT COLLATE "C")) OR NOT (((NEW.authored_by)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.authored_by)::TEXT COLLATE "C")) OR NOT (((NEW.recorded_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.recorded_at)::TEXT COLLATE "C")) OR NOT (((NEW.amends_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.amends_id)::TEXT COLLATE "C")) OR NOT (((NEW.amendment_reason)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.amendment_reason)::TEXT COLLATE "C")) OR NOT (((NEW.created_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_at)::TEXT COLLATE "C")) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Clinical identity, authorship, version and finalized history are protected.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_clinical_records_preserve_history" BEFORE UPDATE ON "clinical_records" FOR EACH ROW EXECUTE FUNCTION "guard_clinical_records_preserve_history"();

CREATE OR REPLACE FUNCTION "guard_clinical_records_require_payload"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.status = 'signed' AND NOT ((NEW.kind = 'vitals' AND EXISTS (SELECT 1 FROM vital_signs p WHERE p.clinical_record_id = NEW.id FOR UPDATE)) OR (NEW.kind = 'entry' AND EXISTS (SELECT 1 FROM clinical_entries p WHERE p.clinical_record_id = NEW.id FOR UPDATE)) OR (NEW.kind = 'diagnosis' AND EXISTS (SELECT 1 FROM diagnoses p WHERE p.clinical_record_id = NEW.id FOR UPDATE)) OR (NEW.kind = 'procedure' AND EXISTS (SELECT 1 FROM clinical_procedures p WHERE p.clinical_record_id = NEW.id FOR UPDATE)) OR (NEW.kind = 'prescription' AND EXISTS (SELECT 1 FROM prescriptions p WHERE p.clinical_record_id = NEW.id FOR UPDATE) AND EXISTS (SELECT 1 FROM prescription_items i WHERE i.prescription_id = NEW.id FOR UPDATE))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Signing requires the matching clinical content.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g004_clinical_records_require_payload" BEFORE UPDATE ON "clinical_records" FOR EACH ROW EXECUTE FUNCTION "guard_clinical_records_require_payload"();

CREATE OR REPLACE FUNCTION "guard_care_sign_template"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.status = 'signed' AND EXISTS
            (SELECT 1 FROM care_record_links l WHERE l.clinical_record_id = NEW.id) AND NOT EXISTS
            (SELECT 1 FROM care_record_links l JOIN care_programs p ON p.id = l.care_program_id
                JOIN clinical_entries e ON e.clinical_record_id = NEW.id
                JOIN clinical_template_versions v ON v.id = e.clinical_template_version_id
                JOIN clinical_templates t ON t.id = v.clinical_template_id
                WHERE l.clinical_record_id = NEW.id AND p.status = 'active'
                    AND ((LEFT(t.code, CHAR_LENGTH(CONCAT('care.', CASE WHEN l.birth_id IS NULL THEN p.type ELSE 'birth' END, '.'))))::TEXT COLLATE "C") = ((CONCAT('care.', CASE WHEN l.birth_id IS NULL THEN p.type ELSE 'birth' END, '.'))::TEXT COLLATE "C")) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid or immutable care-program record.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g005_care_sign_template" BEFORE UPDATE ON "clinical_records" FOR EACH ROW EXECUTE FUNCTION "guard_care_sign_template"();

