CREATE OR REPLACE FUNCTION "guard_clinical_revisions_validate"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.recorded_at IS NOT NULL AND EXISTS (SELECT 1 FROM clinical_records r WHERE r.id = NEW.clinical_record_id
                AND r.version = NEW.version AND r.authored_by = NEW.actor_id AND NEW.recorded_at >= r.recorded_at
                AND (NEW.snapshot #>> '{id}') = (r.id)::text AND (NEW.snapshot #>> '{patient_id}') = (r.patient_id)::text AND (NEW.snapshot #>> '{encounter_id}') = (r.encounter_id)::text AND (NEW.snapshot #>> '{version}') = (r.version)::text AND (NEW.snapshot #>> '{kind}') = r.kind AND (NEW.snapshot #>> '{status}') = r.status
                AND ((NEW.operation = 'created' AND NEW.version = 1 AND r.status = 'draft' AND NEW.reason IS NULL)
                    OR (NEW.operation = 'updated' AND NEW.version > 1 AND r.status = 'draft' AND NEW.reason IS NULL)
                    OR (NEW.operation = 'signed' AND NEW.version > 1 AND r.status = 'signed' AND NEW.reason IS NULL)
                    OR (NEW.operation = 'amended' AND NEW.version > 1 AND r.status = 'signed' AND r.amends_id IS NOT NULL
                        AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000)
                    OR (NEW.operation = 'voided' AND NEW.version > 1 AND r.status = 'voided'
                        AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000)))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid private clinical revision.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_clinical_revisions_validate" BEFORE INSERT ON "clinical_revisions" FOR EACH ROW EXECUTE FUNCTION "guard_clinical_revisions_validate"();

