            AND CHAR_LENGTH(trim(NEW.name)) BETWEEN 1 AND 160 AND NEW.is_active IN (0, 1)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid clinical storage value.'; END IF; RETURN NEW; END;
