CREATE OR REPLACE FUNCTION "guard_clinical_templates_identity"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NOT (((NEW.id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.id)::TEXT COLLATE "C")) OR NOT (((NEW.code)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.code)::TEXT COLLATE "C")) OR NOT (((NEW.created_by)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_by)::TEXT COLLATE "C")) OR NOT (((NEW.created_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_at)::TEXT COLLATE "C")) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Template identity is permanent.'; END IF; RETURN NEW; END;
$guard$;

