            AND ((NEW.code IS NULL AND NEW.code_system IS NULL AND NEW.code_system_version IS NULL)
                OR (CHAR_LENGTH(trim(NEW.code)) BETWEEN 1 AND 64 AND CHAR_LENGTH(trim(NEW.code_system)) BETWEEN 1 AND 32
                    AND CHAR_LENGTH(trim(NEW.code_system_version)) BETWEEN 1 AND 32))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid clinical storage value.'; END IF; RETURN NEW; END;
