CREATE OR REPLACE FUNCTION "guard_doctor_assignments_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.version > 0
            AND (NEW.consultation_type IS NULL OR octet_length(trim(NEW.consultation_type)) BETWEEN 1 AND 64)
            AND EXISTS (SELECT 1 FROM encounters e WHERE e.id = NEW.encounter_id AND NEW.assigned_at >= e.opened_at
                AND e.status IN ('open', 'in_progress') AND (NEW.status <> 'accepted' OR e.status = 'in_progress'))
            AND ((NEW.status = 'assigned' AND NEW.accepted_at IS NULL AND NEW.ended_at IS NULL AND NEW.ended_by IS NULL AND NEW.end_reason IS NULL)
                OR (NEW.status = 'accepted' AND NEW.accepted_at >= NEW.assigned_at AND NEW.ended_at IS NULL AND NEW.ended_by IS NULL AND NEW.end_reason IS NULL)
                OR (NEW.status IN ('completed', 'cancelled', 'reassigned') AND NEW.ended_at >= NEW.assigned_at AND NEW.ended_by IS NOT NULL
                    AND (NEW.accepted_at IS NULL OR (NEW.accepted_at >= NEW.assigned_at AND NEW.ended_at >= NEW.accepted_at))
                    AND (NEW.status <> 'completed' OR NEW.accepted_at IS NOT NULL)
                    AND (NEW.status <> 'cancelled' OR NEW.accepted_at IS NULL)
                    AND (NEW.status = 'completed' OR octet_length(trim(NEW.end_reason)) > 0)))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid visit record.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_doctor_assignments_validate_insert" BEFORE INSERT ON "doctor_assignments" FOR EACH ROW EXECUTE FUNCTION "guard_doctor_assignments_validate_insert"();

CREATE OR REPLACE FUNCTION "guard_assignments_start_assigned"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.status <> 'assigned' OR NEW.version <> 1
            OR EXISTS (SELECT 1 FROM doctor_assignments d WHERE d.encounter_id = NEW.encounter_id AND d.ended_at > NEW.assigned_at) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Assignments must start assigned at version one after earlier assignments ended.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_assignments_start_assigned" BEFORE INSERT ON "doctor_assignments" FOR EACH ROW EXECUTE FUNCTION "guard_assignments_start_assigned"();

