CREATE OR REPLACE FUNCTION "guard_assignments_preserve_history"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.id <> OLD.id OR NEW.encounter_id <> OLD.encounter_id OR NEW.doctor_id <> OLD.doctor_id
            OR NEW.assigned_by <> OLD.assigned_by OR NOT (((NEW.assigned_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.assigned_at)::TEXT COLLATE "C")) OR NOT (((NEW.consultation_type)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.consultation_type)::TEXT COLLATE "C"))
            OR NOT (((NEW.created_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_at)::TEXT COLLATE "C")) OR NEW.version <> OLD.version + 1
            OR OLD.status NOT IN ('assigned', 'accepted') OR NEW.status = OLD.status
            OR (OLD.status = 'assigned' AND NEW.status <> 'accepted' AND NEW.accepted_at IS NOT NULL)
            OR (OLD.accepted_at IS NOT NULL AND NOT (((NEW.accepted_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.accepted_at)::TEXT COLLATE "C")))
            OR NOT ((OLD.status = 'assigned' AND NEW.status IN ('accepted', 'cancelled', 'reassigned'))
                OR (OLD.status = 'accepted' AND NEW.status IN ('completed', 'reassigned'))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Assignment history, version or transition is invalid.'; END IF; RETURN NEW; END;
$guard$;

