BEGIN
                IF (CHAR_LENGTH(trim(NEW.batch_number)) BETWEEN 1 AND 128
            AND CHAR_LENGTH(trim(NEW.manufacturer)) BETWEEN 1 AND 191 AND NEW.expires_on IS NOT NULL
            AND (NEW.manufactured_on IS NULL OR NEW.manufactured_on <= NEW.expires_on)
            AND EXISTS (SELECT 1 FROM drugs d WHERE d.id = NEW.drug_id AND NEW.recorded_at >= d.recorded_at)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
