CREATE OR REPLACE FUNCTION "guard_drug_packs_series"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
DECLARE parent_lock BIGINT ; current_version INT  DEFAULT NULL;
BEGIN
            SELECT id INTO parent_lock FROM drugs WHERE id = NEW.drug_id FOR UPDATE;
            SELECT version INTO current_version FROM stock_series_heads h WHERE h.drug_id = NEW.drug_id AND h.kind = 'pack' AND h.code = (NEW.code) FOR UPDATE;
            IF current_version IS NULL THEN
                INSERT INTO stock_series_heads (drug_id,kind,code) VALUES (NEW.drug_id,'pack',NEW.code);
            END IF;IF (NEW.is_active IN (0,1) AND NEW.version > 0
            AND NEW.base_quantity_micros BETWEEN 1 AND 999999999999999
            AND EXISTS (SELECT 1 FROM drugs d WHERE d.id = NEW.drug_id AND NEW.recorded_at >= d.recorded_at
                AND NEW.base_quantity_micros % (CASE d.quantity_scale WHEN 0 THEN 1000000 WHEN 1 THEN 100000 WHEN 2 THEN 10000 WHEN 3 THEN 1000 WHEN 4 THEN 100 WHEN 5 THEN 10 ELSE 1 END) = 0) AND EXISTS (SELECT 1 FROM stock_series_heads h WHERE h.drug_id = NEW.drug_id AND h.kind = 'pack' AND h.code = (NEW.code) AND NEW.version = h.version + 1
            AND (h.recorded_at IS NULL OR NEW.recorded_at >= h.recorded_at) FOR UPDATE)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

