CREATE OR REPLACE FUNCTION "guard_drug_prices_series"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
DECLARE parent_lock BIGINT ; current_version INT  DEFAULT NULL;
BEGIN
            SELECT id INTO parent_lock FROM drugs WHERE id = NEW.drug_id FOR UPDATE;
            SELECT version INTO current_version FROM stock_series_heads h WHERE h.drug_id = NEW.drug_id AND h.kind = 'price' AND h.code = (CONCAT(NEW.kind, ':', NEW.currency)) FOR UPDATE;
            IF current_version IS NULL THEN
                INSERT INTO stock_series_heads (drug_id,kind,code) VALUES (NEW.drug_id,'price',CONCAT(NEW.kind, ':', NEW.currency));
            END IF;IF (NEW.kind IN ('cost','selling') AND REGEXP_LIKE(NEW.currency, '^[A-Z]{3}$', 'c')
            AND NEW.amount_micros BETWEEN 0 AND 999999999999999 AND NEW.version > 0
            AND EXISTS (SELECT 1 FROM drugs d WHERE d.id = NEW.drug_id AND NEW.recorded_at >= d.recorded_at)
            AND NEW.effective_at >= NEW.recorded_at AND EXISTS (SELECT 1 FROM stock_series_heads h WHERE h.drug_id = NEW.drug_id AND h.kind = 'price' AND h.code = (CONCAT(NEW.kind, ':', NEW.currency)) AND NEW.version = h.version + 1
            AND (h.recorded_at IS NULL OR NEW.recorded_at >= h.recorded_at) AND (h.effective_at IS NULL OR NEW.effective_at >= h.effective_at) FOR UPDATE)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
