CREATE OR REPLACE FUNCTION "guard_drugs_version"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NOT (((NEW.id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.id)::TEXT COLLATE "C")) OR NOT (((NEW.code)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.code)::TEXT COLLATE "C")) OR NOT (((NEW.created_by)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_by)::TEXT COLLATE "C")) OR NOT (((NEW.recorded_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.recorded_at)::TEXT COLLATE "C")) OR NOT (((NEW.reason)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.reason)::TEXT COLLATE "C")) OR NOT (((NEW.name)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.name)::TEXT COLLATE "C")) OR NOT (((NEW.generic_name)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.generic_name)::TEXT COLLATE "C")) OR NOT (((NEW.brand_name)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.brand_name)::TEXT COLLATE "C")) OR NOT (((NEW.strength)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.strength)::TEXT COLLATE "C")) OR NOT (((NEW.dosage_form)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.dosage_form)::TEXT COLLATE "C")) OR NOT (((NEW.category)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.category)::TEXT COLLATE "C")) OR NOT (((NEW.base_unit_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.base_unit_id)::TEXT COLLATE "C")) OR NOT (((NEW.quantity_scale)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.quantity_scale)::TEXT COLLATE "C")) OR NEW.version <> OLD.version + 1 OR NEW.updated_at < OLD.updated_at THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_drugs_version" BEFORE UPDATE ON "drugs" FOR EACH ROW EXECUTE FUNCTION "guard_drugs_version"();

CREATE OR REPLACE FUNCTION "guard_drugs_retain"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF 1 = 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN OLD; END;
$guard$;

CREATE TRIGGER "g001_drugs_retain" BEFORE DELETE ON "drugs" FOR EACH ROW EXECUTE FUNCTION "guard_drugs_retain"();

CREATE OR REPLACE FUNCTION "guard_encounter_revisions_validate"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.version > 0 AND NEW.operation IN ('opened', 'assigned', 'reassigned', 'accepted', 'completed', 'cancelled')
                AND ((NEW.operation = 'opened' AND NEW.version = 1 AND NEW.reason IS NULL)
                    OR (NEW.operation <> 'opened' AND NEW.version > 1 AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000))
                AND ((NEW.snapshot #>> '{id}'))::BIGINT = NEW.encounter_id AND ((NEW.snapshot #>> '{version}'))::BIGINT = NEW.version
                AND EXISTS (SELECT 1 FROM encounters e WHERE e.id = NEW.encounter_id AND e.version = NEW.version)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid encounter history snapshot.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_encounter_revisions_validate" BEFORE INSERT ON "encounter_revisions" FOR EACH ROW EXECUTE FUNCTION "guard_encounter_revisions_validate"();

CREATE OR REPLACE FUNCTION "guard_encounter_revisions_no_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF 1 = 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Encounter history is append-only.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_encounter_revisions_no_update" BEFORE UPDATE ON "encounter_revisions" FOR EACH ROW EXECUTE FUNCTION "guard_encounter_revisions_no_update"();

