CREATE OR REPLACE FUNCTION "guard_encounters_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (octet_length(trim(NEW.visit_type)) BETWEEN 1 AND 64
            AND NEW.care_setting IN ('OPD', 'IPD', 'EMERGENCY') AND NEW.version > 0
            AND ((NEW.status IN ('open', 'in_progress') AND NEW.closed_at IS NULL)
                OR (NEW.status IN ('closed', 'cancelled') AND NEW.closed_at IS NOT NULL AND NEW.closed_at >= NEW.opened_at))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid visit record.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_encounters_validate_insert" BEFORE INSERT ON "encounters" FOR EACH ROW EXECUTE FUNCTION "guard_encounters_validate_insert"();

CREATE OR REPLACE FUNCTION "guard_encounters_start_open"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.status <> 'open' OR NEW.version <> 1
            OR NOT EXISTS (SELECT 1 FROM patients p WHERE p.id = NEW.patient_id AND p.category_id = NEW.category_id)
            OR (NEW.appointment_id IS NOT NULL AND NOT EXISTS
                (SELECT 1 FROM appointments a WHERE a.id = NEW.appointment_id AND a.patient_id = NEW.patient_id AND a.status = 'attended')) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Encounters must start open with matching patient, category and attended booking.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_encounters_start_open" BEFORE INSERT ON "encounters" FOR EACH ROW EXECUTE FUNCTION "guard_encounters_start_open"();

CREATE OR REPLACE FUNCTION "guard_encounters_validate_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (octet_length(trim(NEW.visit_type)) BETWEEN 1 AND 64
            AND NEW.care_setting IN ('OPD', 'IPD', 'EMERGENCY') AND NEW.version > 0
            AND ((NEW.status IN ('open', 'in_progress') AND NEW.closed_at IS NULL)
                OR (NEW.status IN ('closed', 'cancelled') AND NEW.closed_at IS NOT NULL AND NEW.closed_at >= NEW.opened_at))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid visit record.'; END IF; RETURN NEW; END;
$guard$;

