CREATE OR REPLACE FUNCTION "guard_encounters_preserve_lifecycle"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.id <> OLD.id OR NEW.patient_id <> OLD.patient_id OR NOT (((NEW.appointment_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.appointment_id)::TEXT COLLATE "C"))
            OR NEW.category_id <> OLD.category_id OR NEW.opened_by <> OLD.opened_by OR NOT (((NEW.opened_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.opened_at)::TEXT COLLATE "C"))
            OR NOT (((NEW.created_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_at)::TEXT COLLATE "C")) OR NEW.version <> OLD.version + 1
            OR OLD.status NOT IN ('open', 'in_progress')
            OR NOT (NEW.status = OLD.status OR (OLD.status = 'open' AND NEW.status IN ('in_progress', 'cancelled'))
                OR (OLD.status = 'in_progress' AND NEW.status = 'closed'))
            OR (OLD.status = 'in_progress' AND (NOT (((NEW.visit_type)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.visit_type)::TEXT COLLATE "C")) OR NOT (((NEW.care_setting)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.care_setting)::TEXT COLLATE "C"))))
            OR (NEW.status IN ('closed', 'cancelled') AND EXISTS
                (SELECT 1 FROM doctor_assignments d WHERE d.encounter_id = OLD.id AND d.ended_at IS NULL FOR UPDATE))
            OR (NEW.status = 'cancelled' AND EXISTS
                (SELECT 1 FROM doctor_assignments d WHERE d.encounter_id = OLD.id AND d.accepted_at IS NOT NULL FOR UPDATE))
            OR (NEW.closed_at IS NOT NULL AND EXISTS
                (SELECT 1 FROM doctor_assignments d WHERE d.encounter_id = OLD.id AND d.ended_at > NEW.closed_at FOR UPDATE)) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Encounter identity, assignment state, version or transition is invalid.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_encounters_preserve_lifecycle" BEFORE UPDATE ON "encounters" FOR EACH ROW EXECUTE FUNCTION "guard_encounters_preserve_lifecycle"();

CREATE OR REPLACE FUNCTION "guard_encounters_preserve_admissions"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.status IN ('closed', 'cancelled') AND EXISTS
            (SELECT 1 FROM admissions a WHERE a.encounter_id = OLD.id
                AND (a.status <> 'discharged' OR a.discharged_at > NEW.closed_at) FOR UPDATE) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'An encounter cannot end before its admission is discharged.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_encounters_preserve_admissions" BEFORE UPDATE ON "encounters" FOR EACH ROW EXECUTE FUNCTION "guard_encounters_preserve_admissions"();

CREATE OR REPLACE FUNCTION "guard_encounter_pending_investigations"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.status IN ('closed','cancelled') AND (EXISTS
            (SELECT 1 FROM investigation_items i WHERE i.encounter_id = OLD.id AND i.status IN ('requested','collected','processing'))  OR EXISTS (SELECT 1 FROM investigation_results r WHERE r.encounter_id = OLD.id
            AND (r.status IN ('draft','submitted','verified') OR r.last_changed_at > NEW.closed_at))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation request integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g004_encounter_pending_investigations" BEFORE UPDATE ON "encounters" FOR EACH ROW EXECUTE FUNCTION "guard_encounter_pending_investigations"();

