CREATE OR REPLACE FUNCTION "guard_hmo_decision_line_scope"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NOT EXISTS (SELECT 1 FROM hmo_decisions d JOIN hmo_claims c ON c.id=d.claim_id
            JOIN billing_invoice_items i ON i.invoice_id=c.invoice_id JOIN hmo_invoice_shares s ON s.item_id=i.id
            WHERE d.id=NEW.decision_id AND i.id=NEW.item_id AND NEW.approved_kobo<=s.insurer_kobo)
