CREATE OR REPLACE FUNCTION "guard_hmo_review_independent"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.outcome NOT IN ('accepted','rejected') OR NOT ((NEW.kind='tariff' AND EXISTS (SELECT 1 FROM hmo_tariff_imports r WHERE r.id=NEW.record_id AND r.actor_id<>NEW.actor_id AND r.recorded_at<=NEW.recorded_at)) OR (NEW.kind='decision' AND EXISTS (SELECT 1 FROM hmo_decisions r WHERE r.id=NEW.record_id AND r.actor_id<>NEW.actor_id AND r.recorded_at<=NEW.recorded_at)) OR (NEW.kind='remittance' AND EXISTS (SELECT 1 FROM hmo_remittances r WHERE r.id=NEW.record_id AND r.actor_id<>NEW.actor_id AND r.recorded_at<=NEW.recorded_at)) OR (NEW.kind='allocation' AND EXISTS (SELECT 1 FROM hmo_allocations r WHERE r.id=NEW.record_id AND r.actor_id<>NEW.actor_id AND r.recorded_at<=NEW.recorded_at)))
                THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'HMO integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_hmo_review_independent" BEFORE INSERT ON "hmo_reviews" FOR EACH ROW EXECUTE FUNCTION "guard_hmo_review_independent"();

CREATE OR REPLACE FUNCTION "guard_hmo_review_scope"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (
            (NEW.kind='tariff' AND NEW.account_id IS NULL AND EXISTS (SELECT 1 FROM hmo_tariff_imports i JOIN hmo_plans p ON p.id=i.plan_id
                WHERE i.id=NEW.record_id AND p.provider_id=NEW.provider_id)
                AND ((NEW.outcome='accepted' AND NEW.published_version>0 AND NEW.effective_at>=NEW.recorded_at)
                    OR (NEW.outcome='rejected' AND NEW.published_version IS NULL AND NEW.effective_at IS NULL)))
            OR (NEW.kind='remittance' AND NEW.account_id IS NULL AND NEW.published_version IS NULL AND NEW.effective_at IS NULL
                AND EXISTS (SELECT 1 FROM hmo_remittances r WHERE r.id=NEW.record_id AND r.provider_id=NEW.provider_id))
            OR (NEW.kind='decision' AND NEW.published_version IS NULL AND NEW.effective_at IS NULL AND EXISTS (
                SELECT 1 FROM hmo_decisions d JOIN hmo_claims c ON c.id=d.claim_id JOIN hmo_invoice_links l ON l.invoice_id=c.invoice_id
                JOIN hmo_coverages v ON v.id=l.coverage_id JOIN hmo_plans p ON p.id=v.plan_id
                WHERE d.id=NEW.record_id AND c.account_id=NEW.account_id AND p.provider_id=NEW.provider_id))
            OR (NEW.kind='allocation' AND NEW.published_version IS NULL AND NEW.effective_at IS NULL AND EXISTS (
                SELECT 1 FROM hmo_allocations a JOIN hmo_remittances r ON r.id=a.remittance_id
                WHERE a.id=NEW.record_id AND a.account_id=NEW.account_id AND r.provider_id=NEW.provider_id))) IS NOT TRUE
                THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'HMO integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_hmo_review_scope" BEFORE INSERT ON "hmo_reviews" FOR EACH ROW EXECUTE FUNCTION "guard_hmo_review_scope"();

