CREATE OR REPLACE FUNCTION "guard_hmo_revocation_scope"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NOT ((NEW.kind='coverage' AND EXISTS (
            SELECT 1 FROM hmo_coverages c WHERE c.id=NEW.record_id AND c.account_id=NEW.account_id)) OR (NEW.kind='preauth' AND EXISTS (
            SELECT 1 FROM hmo_preauthorizations p WHERE p.id=NEW.record_id AND p.account_id=NEW.account_id)))
                THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'HMO integrity violation'; END IF; RETURN NEW; END;
$guard$;

