CREATE OR REPLACE FUNCTION "guard_investigation_item_initial"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version = 1 AND NEW.status = 'requested'
            AND NEW.priority IN ('routine','urgent') AND NEW.collected_at IS NULL AND NEW.collected_by IS NULL AND NEW.specimen_ref IS NULL
            AND NEW.processing_at IS NULL AND NEW.processing_by IS NULL AND NEW.cancelled_at IS NULL AND NEW.cancelled_by IS NULL AND NEW.cancellation_reason IS NULL
            AND (SELECT COUNT(*) FROM investigation_items i WHERE i.order_id = NEW.order_id) < 20
            AND NOT EXISTS (SELECT 1 FROM investigation_revisions r WHERE r.order_id = NEW.order_id)
            AND EXISTS (SELECT 1 FROM investigation_orders o JOIN encounters e ON e.id = o.encounter_id WHERE o.id = NEW.order_id
                AND o.encounter_id = NEW.encounter_id AND o.version = 1 AND e.status IN ('open','in_progress') AND NEW.last_event_at = o.requested_at)
            AND EXISTS (SELECT 1 FROM investigation_tests t JOIN investigation_schemas s ON s.test_id = t.id WHERE t.id = NEW.test_id
                AND t.is_active = 1 AND t.department = NEW.department AND s.id = NEW.schema_id AND s.version = t.version AND s.published_at <= NEW.last_event_at)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation request integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_investigation_item_initial" BEFORE INSERT ON "investigation_items" FOR EACH ROW EXECUTE FUNCTION "guard_investigation_item_initial"();

CREATE OR REPLACE FUNCTION "guard_investigation_item_transition"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.id = OLD.id AND NEW.order_id = OLD.order_id
            AND NEW.encounter_id = OLD.encounter_id AND NEW.test_id = OLD.test_id AND NEW.schema_id = OLD.schema_id AND NEW.department = OLD.department
            AND NEW.priority = OLD.priority AND NEW.version = OLD.version + 1 AND NEW.last_event_at >= OLD.last_event_at
            AND EXISTS (SELECT 1 FROM encounters e JOIN patients p ON p.id = e.patient_id WHERE e.id = OLD.encounter_id
                AND e.status IN ('open','in_progress') AND p.access_status = 'active')
            AND ((OLD.status = 'requested' AND OLD.department = 'laboratory' AND NEW.status = 'collected'
                    AND NEW.collected_by IS NOT NULL AND NEW.collected_at = NEW.last_event_at AND CHAR_LENGTH(trim(NEW.specimen_ref)) BETWEEN 1 AND 191
                    AND NEW.processing_by IS NULL AND NEW.processing_at IS NULL AND NEW.cancelled_by IS NULL AND NEW.cancelled_at IS NULL AND NEW.cancellation_reason IS NULL)
                OR (((OLD.department = 'laboratory' AND OLD.status = 'collected') OR (OLD.department = 'radiology' AND OLD.status = 'requested'))
                    AND NEW.status = 'processing' AND (NEW.collected_at  IS NOT DISTINCT FROM  OLD.collected_at) AND (NEW.collected_by  IS NOT DISTINCT FROM  OLD.collected_by) AND (NEW.specimen_ref  IS NOT DISTINCT FROM  OLD.specimen_ref) AND NEW.processing_by IS NOT NULL AND NEW.processing_at = NEW.last_event_at
                    AND NEW.cancelled_by IS NULL AND NEW.cancelled_at IS NULL AND NEW.cancellation_reason IS NULL)
                OR (OLD.status IN ('requested','collected') AND NEW.status = 'cancelled' AND (NEW.collected_at  IS NOT DISTINCT FROM  OLD.collected_at) AND (NEW.collected_by  IS NOT DISTINCT FROM  OLD.collected_by) AND (NEW.specimen_ref  IS NOT DISTINCT FROM  OLD.specimen_ref)
                    AND NEW.processing_by IS NULL AND NEW.processing_at IS NULL AND NEW.cancelled_by IS NOT NULL AND NEW.cancelled_at = NEW.last_event_at
                    AND CHAR_LENGTH(trim(NEW.cancellation_reason)) BETWEEN 5 AND 2000))  OR (OLD.status = 'processing' AND NEW.status = 'completed' AND (NEW.collected_at  IS NOT DISTINCT FROM  OLD.collected_at) AND (NEW.collected_by  IS NOT DISTINCT FROM  OLD.collected_by) AND (NEW.specimen_ref  IS NOT DISTINCT FROM  OLD.specimen_ref)
            AND NEW.processing_by = OLD.processing_by AND NEW.processing_at = OLD.processing_at
            AND NEW.cancelled_by IS NULL AND NEW.cancelled_at IS NULL AND NEW.cancellation_reason IS NULL
            AND EXISTS (SELECT 1 FROM investigation_results r WHERE r.item_id = OLD.id AND r.status = 'released' AND r.released_at = NEW.last_event_at))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation request integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_investigation_item_transition" BEFORE UPDATE ON "investigation_items" FOR EACH ROW EXECUTE FUNCTION "guard_investigation_item_transition"();

