CREATE OR REPLACE FUNCTION "guard_investigation_order_initial"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version = 1 AND NEW.last_changed_at = NEW.requested_at
            AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000 AND EXISTS
            (SELECT 1 FROM encounters e JOIN patients p ON p.id = e.patient_id JOIN doctor_assignments a ON a.encounter_id = e.id
                WHERE e.id = NEW.encounter_id AND e.patient_id = NEW.patient_id AND p.access_status = 'active'
                AND e.status IN ('open','in_progress') AND a.id = NEW.assignment_id AND a.version = NEW.assignment_version
                AND a.doctor_id = NEW.ordered_by AND a.ended_at IS NULL AND a.status IN ('assigned','accepted')
                AND NEW.requested_at >= e.opened_at AND NEW.requested_at >= a.assigned_at)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation request integrity violation'; END IF; RETURN NEW; END;
$guard$;

