CREATE OR REPLACE FUNCTION "guard_investigation_order_history"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.id = OLD.id AND NEW.patient_id = OLD.patient_id
            AND NEW.encounter_id = OLD.encounter_id AND NEW.ordered_by = OLD.ordered_by AND NEW.assignment_id = OLD.assignment_id
            AND NEW.assignment_version = OLD.assignment_version AND NEW.requested_at = OLD.requested_at AND NEW.reason = OLD.reason
            AND (NEW.clinical_context  IS NOT DISTINCT FROM  OLD.clinical_context) AND NEW.created_at = OLD.created_at AND NEW.version = OLD.version + 1
            AND NEW.last_changed_at >= OLD.last_changed_at
            AND EXISTS (SELECT 1 FROM encounters e JOIN patients p ON p.id = e.patient_id WHERE e.id = OLD.encounter_id
                AND e.status IN ('open','in_progress') AND p.access_status = 'active')) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation request integrity violation'; END IF; RETURN NEW; END;
$guard$;

