CREATE OR REPLACE FUNCTION "guard_investigation_attachment_initial"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (EXISTS
            (SELECT 1 FROM investigation_results r JOIN files f ON f.id = NEW.file_id
                JOIN investigation_result_file_bindings b ON b.file_id = f.id AND b.item_id = r.item_id WHERE r.id = NEW.result_id AND r.status = 'draft'
                AND f.uploaded_by = r.author_id AND f.scan_status IN ('not_scanned','clean')
                AND f.original_name = NEW.original_name AND f.mime_type = NEW.mime_type AND f.byte_size = NEW.byte_size AND f.sha256 = NEW.sha256)
            AND (SELECT COUNT(*) FROM investigation_result_attachments a WHERE a.result_id = NEW.result_id) < 10) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation result integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_investigation_attachment_initial" BEFORE INSERT ON "investigation_result_attachments" FOR EACH ROW EXECUTE FUNCTION "guard_investigation_attachment_initial"();

