CREATE OR REPLACE FUNCTION "guard_investigation_result_revision_sequence"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.operation IN ('created','updated','submitted','verified','released','voided','amended')
            AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000
            AND EXISTS (SELECT 1 FROM investigation_results r WHERE r.id = NEW.result_id AND r.version = NEW.version AND r.last_changed_at = NEW.recorded_at)
            AND NEW.version = (SELECT COALESCE(MAX(h.version),0) + 1 FROM investigation_result_revisions h WHERE h.result_id = NEW.result_id)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation result integrity violation'; END IF; RETURN NEW; END;
$guard$;

