CREATE OR REPLACE FUNCTION "guard_investigation_result_initial"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version = 1 AND NEW.status = 'draft'
            AND NEW.submitted_at IS NULL AND NEW.verified_by IS NULL AND NEW.verified_at IS NULL AND NEW.released_by IS NULL
            AND NEW.released_at IS NULL AND NEW.voided_at IS NULL AND NEW.created_at = NEW.last_changed_at
            AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000 AND EXISTS (SELECT 1 FROM encounters e JOIN patients p ON p.id = e.patient_id WHERE e.id = NEW.encounter_id
            AND e.status IN ('open','in_progress') AND p.access_status = 'active' AND NEW.last_changed_at >= e.opened_at)
            AND EXISTS (SELECT 1 FROM investigation_items i WHERE i.id = NEW.item_id AND i.status IN ('processing','completed') AND NEW.last_changed_at >= i.last_event_at)
            AND NEW.sequence = (SELECT COALESCE(MAX(r.sequence),0) + 1 FROM investigation_results r WHERE r.item_id = NEW.item_id)
            AND NOT EXISTS (SELECT 1 FROM investigation_results r WHERE r.item_id = NEW.item_id AND r.last_changed_at > NEW.last_changed_at)
            AND ((NEW.previous_result_id IS NULL AND NOT EXISTS (SELECT 1 FROM investigation_results r WHERE r.item_id = NEW.item_id AND r.status = 'released'))
                OR EXISTS (SELECT 1 FROM investigation_results r WHERE r.id = NEW.previous_result_id AND r.item_id = NEW.item_id AND r.status = 'released'
                    AND r.released_at <= NEW.last_changed_at AND NOT EXISTS (SELECT 1 FROM investigation_results n WHERE n.previous_result_id = r.id AND n.status = 'released')))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation result integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_investigation_result_initial" BEFORE INSERT ON "investigation_results" FOR EACH ROW EXECUTE FUNCTION "guard_investigation_result_initial"();

CREATE OR REPLACE FUNCTION "guard_investigation_result_lifecycle"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.id = OLD.id AND NEW.item_id = OLD.item_id AND NEW.test_id = OLD.test_id AND NEW.schema_id = OLD.schema_id
            AND NEW.encounter_id = OLD.encounter_id AND (NEW.previous_result_id  IS NOT DISTINCT FROM  OLD.previous_result_id)
            AND NEW.sequence = OLD.sequence AND NEW.author_id = OLD.author_id AND NEW.created_at = OLD.created_at
            AND NEW.version = OLD.version + 1 AND NEW.last_changed_at >= OLD.last_changed_at AND EXISTS (SELECT 1 FROM encounters e JOIN patients p ON p.id = e.patient_id WHERE e.id = NEW.encounter_id
            AND e.status IN ('open','in_progress') AND p.access_status = 'active' AND NEW.last_changed_at >= e.opened_at)
            AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000 AND (
                (OLD.status = 'draft' AND NEW.status IN ('draft','submitted','voided') AND NEW.verified_by IS NULL AND NEW.verified_at IS NULL
                    AND NEW.released_by IS NULL AND NEW.released_at IS NULL
                    AND ((NEW.status = 'draft' AND NEW.submitted_at IS NULL AND NEW.voided_at IS NULL)
                        OR (NEW.status = 'submitted' AND NEW.submitted_at = NEW.last_changed_at AND NEW.voided_at IS NULL AND (NEW.fields  IS NOT DISTINCT FROM  OLD.fields) AND (NEW.comment  IS NOT DISTINCT FROM  OLD.comment) AND NEW.reason = OLD.reason)
                        OR (NEW.status = 'voided' AND NEW.voided_at = NEW.last_changed_at AND NEW.submitted_at IS NULL AND (NEW.fields  IS NOT DISTINCT FROM  OLD.fields) AND (NEW.comment  IS NOT DISTINCT FROM  OLD.comment) AND NEW.reason = OLD.reason)))
                OR (OLD.status = 'submitted' AND NEW.status IN ('verified','voided') AND (NEW.fields  IS NOT DISTINCT FROM  OLD.fields) AND (NEW.comment  IS NOT DISTINCT FROM  OLD.comment) AND NEW.reason = OLD.reason
                    AND NEW.submitted_at = OLD.submitted_at AND NEW.released_by IS NULL AND NEW.released_at IS NULL
                    AND ((NEW.status = 'verified' AND NEW.verified_by <> NEW.author_id AND NEW.verified_at = NEW.last_changed_at AND NEW.voided_at IS NULL)
                        OR (NEW.status = 'voided' AND NEW.verified_by IS NULL AND NEW.verified_at IS NULL AND NEW.voided_at = NEW.last_changed_at)))
                OR (OLD.status = 'verified' AND NEW.status IN ('released','voided') AND (NEW.fields  IS NOT DISTINCT FROM  OLD.fields) AND (NEW.comment  IS NOT DISTINCT FROM  OLD.comment) AND NEW.reason = OLD.reason
                    AND NEW.submitted_at = OLD.submitted_at AND NEW.verified_by = OLD.verified_by AND NEW.verified_at = OLD.verified_at
                    AND ((NEW.status = 'released' AND NEW.released_by = OLD.verified_by AND NEW.released_by <> NEW.author_id
                            AND NEW.released_at = NEW.last_changed_at AND NEW.voided_at IS NULL
                            AND NOT EXISTS (SELECT 1 FROM investigation_results n WHERE n.item_id = OLD.item_id AND n.status = 'released'
                                AND n.sequence > COALESCE((SELECT p.sequence FROM investigation_results p WHERE p.id = OLD.previous_result_id),0)))
                        OR (NEW.status = 'voided' AND NEW.released_by IS NULL AND NEW.released_at IS NULL AND NEW.voided_at = NEW.last_changed_at))))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation result integrity violation'; END IF; RETURN NEW; END;
$guard$;

