CREATE OR REPLACE FUNCTION "guard_investigation_revision_sequence"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version > 0
            AND NEW.operation IN ('requested','collected','processing','cancelled','completed') AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000
            AND EXISTS (SELECT 1 FROM investigation_orders o WHERE o.id = NEW.order_id AND o.version = NEW.version AND o.last_changed_at = NEW.recorded_at)
            AND NEW.version = (SELECT COALESCE(MAX(r.version),0) + 1 FROM investigation_revisions r WHERE r.order_id = NEW.order_id)
            AND ((NEW.version = 1 AND NEW.operation = 'requested' AND NEW.item_id IS NULL) OR
                (NEW.version > 1 AND NEW.item_id IS NOT NULL AND EXISTS (SELECT 1 FROM investigation_items i WHERE i.id = NEW.item_id AND i.order_id = NEW.order_id AND i.status = NEW.operation)))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation request integrity violation'; END IF; RETURN NEW; END;
$guard$;

