CREATE OR REPLACE FUNCTION "guard_investigation_publication"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version > 0
            AND EXISTS (SELECT 1 FROM investigation_tests t WHERE t.id = NEW.test_id AND t.version = NEW.version)
            AND NEW.version = (SELECT COALESCE(MAX(s.version),0) + 1 FROM investigation_schemas s WHERE s.test_id = NEW.test_id)
            AND CHAR_LENGTH(NEW.content_hash) = 64 AND CHAR_LENGTH(trim(NEW.approval_reference)) BETWEEN 5 AND 2000
            AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation catalog integrity violation'; END IF; RETURN NEW; END;
$guard$;

