CREATE OR REPLACE FUNCTION "guard_investigation_initial"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version = 1
            AND NEW.department IN ('laboratory','radiology') AND NEW.is_active IN (0,1)
            AND CHAR_LENGTH(trim(NEW.code)) BETWEEN 1 AND 64 AND CHAR_LENGTH(trim(NEW.name)) BETWEEN 1 AND 191
            AND EXISTS (SELECT 1 FROM services s WHERE s.id = NEW.service_id AND s.category = NEW.department AND s.is_active = 1)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation catalog integrity violation'; END IF; RETURN NEW; END;
$guard$;

