BEGIN
                IF (NEW.id = OLD.id AND (NEW.code::text COLLATE "C") = (OLD.code::text COLLATE "C")
            AND NEW.department = OLD.department AND NEW.service_id = OLD.service_id AND NEW.created_by = OLD.created_by
            AND NEW.created_at = OLD.created_at AND NEW.version = OLD.version + 1 AND NEW.is_active IN (0,1)
            AND CHAR_LENGTH(trim(NEW.name)) BETWEEN 1 AND 191
            AND EXISTS (SELECT 1 FROM investigation_schemas s WHERE s.test_id = OLD.id AND s.version = OLD.version)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Investigation catalog integrity violation'; END IF; RETURN NEW; END;
