CREATE OR REPLACE FUNCTION "guard_medication_administration_identity"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.observed_at > NEW.recorded_at
            OR NOT EXISTS (SELECT 1 FROM medication_dispenses d WHERE d.id = NEW.dispense_id AND NEW.observed_at >= d.recorded_at)
            OR (NEW.corrects_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM medication_administrations a
                WHERE a.id = NEW.corrects_id AND a.dispense_id = NEW.dispense_id AND a.actor_id = NEW.actor_id
                    AND NEW.recorded_at >= a.recorded_at)) OR (NEW.corrects_id IS NULL AND NEW.quantity_micros = 0) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication record integrity violation'; END IF; RETURN NEW; END;
$guard$;

