CREATE OR REPLACE FUNCTION "guard_medication_dispense_identity"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NOT EXISTS (
            SELECT 1 FROM medication_authorizations a JOIN drug_batches b ON b.drug_id = a.drug_id
            JOIN stock_movements m ON m.batch_id = b.id WHERE a.id = NEW.authorization_id AND b.id = NEW.batch_id
            AND m.id = NEW.movement_id AND m.drug_id = a.drug_id AND m.store_id = NEW.store_id
            AND m.kind = 'dispense' AND m.quantity_micros = -NEW.quantity_micros
            AND m.reversal_of IS NULL AND m.created_by = NEW.actor_id AND m.recorded_at = NEW.recorded_at) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication record integrity violation'; END IF; RETURN NEW; END;
$guard$;

