CREATE OR REPLACE FUNCTION "guard_medication_event_sequence"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.version NOT BETWEEN 1 AND 4294967293
            OR (NEW.version = 1 AND NEW.action <> 'authorize') OR (NEW.version > 1 AND (NEW.action = 'authorize'
                OR NOT EXISTS (SELECT 1 FROM medication_events e WHERE e.authorization_id = NEW.authorization_id
                    AND e.version = NEW.version - 1 AND e.recorded_at <= NEW.recorded_at))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication record integrity violation'; END IF; RETURN NEW; END;
$guard$;

