CREATE OR REPLACE FUNCTION "guard_medication_event_binding"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NOT ((NEW.action = 'authorize' AND EXISTS (SELECT a.id FROM medication_authorizations a WHERE a.id = NEW.authorization_id AND a.id = NEW.record_id)) OR (NEW.action = 'dispense' AND EXISTS (SELECT d.id FROM medication_dispenses d WHERE d.authorization_id = NEW.authorization_id AND d.id = NEW.record_id)) OR (NEW.action = 'return-request' AND EXISTS (SELECT r.id FROM medication_returns r JOIN medication_dispenses d ON d.id = r.dispense_id WHERE d.authorization_id = NEW.authorization_id AND r.id = NEW.record_id)) OR (NEW.action = 'return-approve' AND EXISTS (SELECT v.id FROM medication_return_reviews v JOIN medication_returns r ON r.id = v.return_id JOIN medication_dispenses d ON d.id = r.dispense_id WHERE d.authorization_id = NEW.authorization_id AND v.id = NEW.record_id AND v.decision = 'approved')) OR (NEW.action = 'return-reject' AND EXISTS (SELECT v.id FROM medication_return_reviews v JOIN medication_returns r ON r.id = v.return_id JOIN medication_dispenses d ON d.id = r.dispense_id WHERE d.authorization_id = NEW.authorization_id AND v.id = NEW.record_id AND v.decision = 'rejected')) OR (NEW.action = 'administer' AND EXISTS (SELECT a.id FROM medication_administrations a JOIN medication_dispenses d ON d.id = a.dispense_id WHERE d.authorization_id = NEW.authorization_id AND a.id = NEW.record_id AND a.corrects_id IS NULL)) OR (NEW.action = 'correct' AND EXISTS (SELECT a.id FROM medication_administrations a JOIN medication_dispenses d ON d.id = a.dispense_id WHERE d.authorization_id = NEW.authorization_id AND a.id = NEW.record_id AND a.corrects_id IS NOT NULL))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication record integrity violation'; END IF; RETURN NEW; END;
$guard$;

