BEGIN
                IF CHAR_LENGTH(trim(NEW.reason)) < 5 OR CHAR_LENGTH(NEW.reason) > 2000 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication record integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_medication_return_reviews_signature" BEFORE INSERT ON "medication_return_reviews" FOR EACH ROW EXECUTE FUNCTION "guard_medication_return_reviews_signature"();

CREATE OR REPLACE FUNCTION "guard_medication_return_review_identity"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.decision NOT IN ('approved','rejected')
            OR NOT EXISTS (SELECT 1 FROM medication_returns r JOIN medication_dispenses d ON d.id = r.dispense_id
                WHERE r.id = NEW.return_id AND r.actor_id <> NEW.actor_id AND NEW.recorded_at >= r.recorded_at
                AND ((NEW.decision = 'rejected' AND NEW.movement_id IS NULL)
                    OR (NEW.decision = 'approved' AND ((r.disposition <> 'usable' AND NEW.movement_id IS NULL)
                    OR (r.disposition = 'usable' AND EXISTS (SELECT 1 FROM stock_movements m JOIN medication_authorizations a ON a.id = d.authorization_id
                        WHERE m.id = NEW.movement_id AND m.batch_id = d.batch_id AND m.store_id = d.store_id
                        AND m.drug_id = a.drug_id AND m.kind = 'return' AND m.quantity_micros = r.quantity_micros
                        AND m.reversal_of IS NULL AND m.created_by = NEW.actor_id AND m.recorded_at = NEW.recorded_at)))))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication record integrity violation'; END IF; RETURN NEW; END;
$guard$;

