                IF CHAR_LENGTH(trim(NEW.reason)) < 5 OR CHAR_LENGTH(NEW.reason) > 2000 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication record integrity violation'; END IF; RETURN NEW; END;
