CREATE OR REPLACE FUNCTION "guard_medication_return_disposition"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.disposition NOT IN ('usable','damaged','expired')
            OR NEW.usable_confirmed NOT IN (0,1) OR (NEW.disposition = 'usable' AND NEW.usable_confirmed <> 1)
            OR (NEW.disposition <> 'usable' AND NEW.usable_confirmed <> 0) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication record integrity violation'; END IF; RETURN NEW; END;
$guard$;

