                OR OLD.resolved_at IS NOT NULL OR NEW.resolved_at IS NULL THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Flag history cannot be rewritten.'; END IF; RETURN NEW; END;
