                AND NOT REGEXP_LIKE(NEW.identifier, '[^A-Z0-9/._-]', 'c')
                AND REGEXP_LIKE(LEFT(NEW.identifier, 1), '[A-Z0-9]', 'c')
            AND ((NEW.kind)::TEXT COLLATE "C") IN ('mrn', 'legacy_mrn')
            AND ((NEW.kind = 'mrn' AND NEW.retired_at IS NULL AND EXISTS (
                SELECT 1 FROM patients WHERE id = NEW.patient_id AND mrn = NEW.identifier
            )) OR (NEW.retired_at IS NOT NULL AND NOT EXISTS (
                SELECT 1 FROM patients WHERE id = NEW.patient_id AND mrn = NEW.identifier
            )))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid patient record.'; END IF; RETURN NEW; END;
