BEGIN IF NEW.identifier <> OLD.identifier OR NEW.patient_id <> OLD.patient_id OR ((NEW.kind)::TEXT COLLATE "C") <> ((OLD.kind)::TEXT COLLATE "C")
                OR (OLD.retired_at IS NOT NULL AND (NEW.retired_at IS NULL OR NEW.retired_at <> OLD.retired_at)) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Patient numbers and their ownership are permanent.'; END IF; RETURN NEW; END;
