CREATE OR REPLACE FUNCTION "guard_patient_merge_requests_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.source_patient_id <> NEW.target_patient_id AND NEW.source_version > 0 AND NEW.target_version > 0
            AND octet_length(trim(NEW.reason)) > 0 AND NEW.version > 0
            AND ((NEW.status = 'pending' AND NEW.version = 1 AND NEW.reviewed_at IS NULL AND NEW.reviewed_by IS NULL AND NEW.review_reason IS NULL)
                OR (NEW.status IN ('approved', 'rejected', 'cancelled') AND NEW.version = 2 AND NEW.reviewed_at IS NOT NULL
                    AND NEW.reviewed_by IS NOT NULL AND octet_length(trim(NEW.review_reason)) > 0
                    AND ((NEW.status = 'cancelled' AND NEW.reviewed_by = NEW.requested_by)
                        OR (NEW.status IN ('approved', 'rejected') AND NEW.reviewed_by <> NEW.requested_by))))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid patient management record.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_patient_merge_requests_validate_insert" BEFORE INSERT ON "patient_merge_requests" FOR EACH ROW EXECUTE FUNCTION "guard_patient_merge_requests_validate_insert"();

CREATE OR REPLACE FUNCTION "guard_patient_merge_requests_start_pending"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.status <> 'pending' THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Merge requests must start pending.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_patient_merge_requests_start_pending" BEFORE INSERT ON "patient_merge_requests" FOR EACH ROW EXECUTE FUNCTION "guard_patient_merge_requests_start_pending"();

CREATE OR REPLACE FUNCTION "guard_patient_merge_requests_validate_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.source_patient_id <> NEW.target_patient_id AND NEW.source_version > 0 AND NEW.target_version > 0
            AND octet_length(trim(NEW.reason)) > 0 AND NEW.version > 0
            AND ((NEW.status = 'pending' AND NEW.version = 1 AND NEW.reviewed_at IS NULL AND NEW.reviewed_by IS NULL AND NEW.review_reason IS NULL)
                OR (NEW.status IN ('approved', 'rejected', 'cancelled') AND NEW.version = 2 AND NEW.reviewed_at IS NOT NULL
                    AND NEW.reviewed_by IS NOT NULL AND octet_length(trim(NEW.review_reason)) > 0
                    AND ((NEW.status = 'cancelled' AND NEW.reviewed_by = NEW.requested_by)
                        OR (NEW.status IN ('approved', 'rejected') AND NEW.reviewed_by <> NEW.requested_by))))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid patient management record.'; END IF; RETURN NEW; END;
$guard$;

