CREATE OR REPLACE FUNCTION "guard_patient_merge_requests_preserve_history"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF OLD.status <> 'pending' OR NEW.status = 'pending' OR NEW.source_patient_id <> OLD.source_patient_id
                OR NEW.target_patient_id <> OLD.target_patient_id OR NEW.source_version <> OLD.source_version
                OR NEW.target_version <> OLD.target_version OR NEW.requested_by <> OLD.requested_by OR ((NEW.reason)::TEXT COLLATE "C") <> ((OLD.reason)::TEXT COLLATE "C") THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Merge requests can only be reviewed once.'; END IF; RETURN NEW; END;
$guard$;

