CREATE OR REPLACE FUNCTION "guard_patient_merges_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.source_patient_id <> NEW.target_patient_id AND NEW.source_version > 0 AND NEW.target_version > 0
            AND EXISTS (SELECT 1 FROM patient_merge_requests r WHERE r.id = NEW.request_id AND r.status = 'approved'
                AND r.source_patient_id = NEW.source_patient_id AND r.target_patient_id = NEW.target_patient_id
                AND r.reviewed_by = NEW.approved_by AND r.requested_by <> NEW.approved_by
                AND NEW.source_version = r.source_version + 1 AND NEW.target_version = r.target_version + 1)
            AND NOT EXISTS (SELECT 1 FROM patient_merges m WHERE m.source_patient_id = NEW.target_patient_id)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid patient management record.'; END IF; RETURN NEW; END;
$guard$;

