            AND char_length(trim(NEW.first_name)) BETWEEN 1 AND 64
            AND char_length(trim(NEW.last_name)) BETWEEN 1 AND 64
            AND NEW.version > 0
            AND ((NEW.access_status)::TEXT COLLATE "C") IN ('active', 'restricted', 'merged')
            AND ((NEW.life_status)::TEXT COLLATE "C") IN ('unknown', 'alive', 'deceased')
            AND NEW.dob_estimated IN (0, 1)
            AND (NEW.dob_estimated = 0 OR NEW.date_of_birth IS NOT NULL)
            AND (NEW.deceased_at IS NULL OR NEW.life_status = 'deceased')) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid patient record.'; END IF; RETURN NEW; END;
$guard$;

