CREATE OR REPLACE FUNCTION "guard_patients_reserve_mrn"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
            INSERT INTO patient_identifiers (identifier, kind, patient_id, created_at, updated_at)
            VALUES (NEW.mrn, 'mrn', NEW.id, timezone('UTC', statement_timestamp()), timezone('UTC', statement_timestamp()));
         RETURN NEW; END;
$guard$;

