CREATE OR REPLACE FUNCTION "guard_patients_retain_mrn"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.mrn <> OLD.mrn THEN
            UPDATE patient_identifiers SET retired_at = timezone('UTC', statement_timestamp()), updated_at = timezone('UTC', statement_timestamp())
                WHERE patient_id = NEW.id AND identifier = OLD.mrn;
            INSERT INTO patient_identifiers (identifier, kind, patient_id, created_at, updated_at)
                VALUES (NEW.mrn, 'mrn', NEW.id, timezone('UTC', statement_timestamp()), timezone('UTC', statement_timestamp()));
         END IF; RETURN NEW; END;
$guard$;

