BEGIN IF (NEW.line_number BETWEEN 1 AND 65535 AND CHAR_LENGTH(trim(NEW.medication_name)) BETWEEN 1 AND 255
            AND ((NEW.duration_value IS NULL AND NEW.duration_unit IS NULL)
                OR (NEW.duration_value > 0 AND CHAR_LENGTH(trim(NEW.duration_unit)) BETWEEN 1 AND 32))
            AND ((NEW.quantity IS NULL AND NEW.quantity_unit IS NULL)
                OR (NEW.quantity > 0 AND CHAR_LENGTH(trim(NEW.quantity_unit)) BETWEEN 1 AND 64))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid clinical storage value.'; END IF; RETURN NEW; END;
$guard$;

