CREATE OR REPLACE FUNCTION "guard_reminder_delivery_scope"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.outcome NOT IN ('delivered','suppressed')
            OR (NEW.outcome='delivered' AND NEW.suppression_code IS NOT NULL)
            OR (NEW.outcome='suppressed' AND NEW.suppression_code IS NULL)
            OR NOT EXISTS (SELECT 1 FROM reminder_occurrences o JOIN reminder_recipients p ON p.revision_id=o.revision_id
                WHERE o.id=NEW.occurrence_id AND p.user_id=NEW.recipient_id)
                THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Reminder integrity violation'; END IF; RETURN NEW; END;
$guard$;

