CREATE OR REPLACE FUNCTION "guard_reminder_occurrence_scope"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.sequence NOT BETWEEN 1 AND 366 OR NEW.processed_at<NEW.due_at
            OR NOT EXISTS (SELECT 1 FROM reminder_revisions v WHERE v.id=NEW.revision_id AND v.reminder_id=NEW.reminder_id AND NEW.sequence<=v.occurrence_count)
                THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Reminder integrity violation'; END IF; RETURN NEW; END;
$guard$;

