CREATE OR REPLACE FUNCTION "guard_billing_price_version"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.version < 1 OR NEW.effective_at < NEW.recorded_at
            OR (NEW.version > 1 AND NOT EXISTS (SELECT 1 FROM service_prices p WHERE p.service_id = NEW.service_id
                AND p.version = NEW.version - 1 AND p.effective_at <= NEW.effective_at AND p.recorded_at <= NEW.recorded_at)) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Billing integrity violation'; END IF; RETURN NEW; END;
$guard$;

