CREATE OR REPLACE FUNCTION "guard_notification_identity"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.id<>OLD.id OR NEW.delivery_id<>OLD.delivery_id OR NEW.recipient_id<>OLD.recipient_id
            OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at
            OR (NEW.read_at IS NOT NULL AND (NEW.read_at<NEW.created_at OR NEW.read_at>NEW.updated_at))
                THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Reminder integrity violation'; END IF; RETURN NEW; END;
$guard$;

