CREATE OR REPLACE FUNCTION "guard_reminder_context"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NEW.version<>1 OR NEW.is_active<>1 OR NEW.next_sequence<>1 OR NEW.next_due_at IS NULL
            OR (NEW.encounter_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM encounters e WHERE e.id=NEW.encounter_id AND e.patient_id=NEW.patient_id))
                THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Reminder integrity violation'; END IF; RETURN NEW; END;
$guard$;

