CREATE OR REPLACE FUNCTION "guard_stock_catalog_revision_valid"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.catalog IN ('units','drugs','packs','suppliers','stores','batches','prices','store-access')
            AND NEW.record_id > 0 AND NEW.version > 0 AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_stock_catalog_revision_valid" BEFORE INSERT ON "stock_catalog_revisions" FOR EACH ROW EXECUTE FUNCTION "guard_stock_catalog_revision_valid"();

CREATE OR REPLACE FUNCTION "guard_stock_catalog_revision_reference"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NOT ((NEW.catalog = 'units' AND EXISTS (SELECT 1 FROM stock_units r WHERE r.id = NEW.record_id
                AND NEW.version = 1 AND NEW.recorded_at >= r.recorded_at)) OR (NEW.catalog = 'drugs' AND EXISTS (SELECT 1 FROM drugs r WHERE r.id = NEW.record_id
                AND NEW.version = r.version AND NEW.recorded_at >= r.updated_at)) OR (NEW.catalog = 'packs' AND EXISTS (SELECT 1 FROM drug_packs r WHERE r.id = NEW.record_id
                AND NEW.version = r.version AND NEW.recorded_at >= r.recorded_at)) OR (NEW.catalog = 'suppliers' AND EXISTS (SELECT 1 FROM suppliers r WHERE r.id = NEW.record_id
                AND NEW.version = r.version AND NEW.recorded_at >= r.updated_at)) OR (NEW.catalog = 'stores' AND EXISTS (SELECT 1 FROM stock_stores r WHERE r.id = NEW.record_id
                AND NEW.version = r.version AND NEW.recorded_at >= r.updated_at)) OR (NEW.catalog = 'batches' AND EXISTS (SELECT 1 FROM drug_batches r WHERE r.id = NEW.record_id
                AND NEW.version = 1 AND NEW.recorded_at >= r.recorded_at)) OR (NEW.catalog = 'prices' AND EXISTS (SELECT 1 FROM drug_prices r WHERE r.id = NEW.record_id
                AND NEW.version = r.version AND NEW.recorded_at >= r.recorded_at)) OR (NEW.catalog = 'store-access' AND EXISTS (SELECT 1 FROM stock_store_accesses r WHERE r.id = NEW.record_id
                AND NEW.version = r.version AND NEW.recorded_at >= r.changed_at))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

