                IF (octet_length(NEW.invoice_key) = 64 AND EXISTS (SELECT 1 FROM stock_operations o
            WHERE o.id = NEW.operation_id AND o.kind = 'receipt' AND o.status = 'posting' AND o.supplier_id = NEW.supplier_id)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

