CREATE OR REPLACE FUNCTION "guard_stock_movements_provenance"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000 AND NEW.recorded_at IS NOT NULL) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_stock_movements_provenance" BEFORE INSERT ON "stock_movements" FOR EACH ROW EXECUTE FUNCTION "guard_stock_movements_provenance"();

CREATE OR REPLACE FUNCTION "guard_stock_movement_valid"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.quantity_micros BETWEEN -999999999999999 AND 999999999999999
            AND NEW.quantity_micros <> 0 AND CHAR_LENGTH(trim(NEW.movement_key)) BETWEEN 1 AND 64
            AND CHAR_LENGTH(trim(NEW.reference_type)) BETWEEN 1 AND 64 AND CHAR_LENGTH(trim(NEW.reference_id)) BETWEEN 1 AND 128
            AND ((NEW.unit_cost_micros IS NULL AND NEW.currency IS NULL)
                OR (NEW.unit_cost_micros BETWEEN 0 AND 999999999999999 AND REGEXP_LIKE(NEW.currency, '^[A-Z]{3}$', 'c')))
            AND ((NEW.kind IN ('opening','receipt','return') AND NEW.quantity_micros > 0 AND NEW.reversal_of IS NULL)
                OR (NEW.kind IN ('dispense','damage','expiry') AND NEW.quantity_micros < 0 AND NEW.reversal_of IS NULL)
                OR (NEW.kind IN ('transfer','adjustment') AND NEW.reversal_of IS NULL)
                OR (NEW.kind = 'reversal' AND NEW.reversal_of IS NOT NULL))
            AND EXISTS (SELECT 1 FROM drugs d WHERE d.id = NEW.drug_id AND NEW.quantity_micros % (CASE d.quantity_scale WHEN 0 THEN 1000000 WHEN 1 THEN 100000 WHEN 2 THEN 10000 WHEN 3 THEN 1000 WHEN 4 THEN 100 WHEN 5 THEN 10 ELSE 1 END) = 0)
            AND EXISTS (SELECT 1 FROM drug_batches b WHERE b.id = NEW.batch_id AND NEW.recorded_at >= b.recorded_at)
            AND EXISTS (SELECT 1 FROM stock_stores s WHERE s.id = NEW.store_id AND NEW.recorded_at >= s.recorded_at)
            AND (NEW.pack_id IS NULL OR EXISTS (SELECT 1 FROM drug_packs p WHERE p.id = NEW.pack_id AND NEW.recorded_at >= p.recorded_at))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_stock_movement_valid" BEFORE INSERT ON "stock_movements" FOR EACH ROW EXECUTE FUNCTION "guard_stock_movement_valid"();

CREATE OR REPLACE FUNCTION "guard_stock_reversal_valid"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.reversal_of IS NOT NULL AND NOT EXISTS
            (SELECT 1 FROM stock_movements m WHERE m.id = NEW.reversal_of AND m.kind <> 'reversal'
                AND m.store_id = NEW.store_id AND m.batch_id = NEW.batch_id AND m.drug_id = NEW.drug_id
                AND m.quantity_micros = -NEW.quantity_micros AND NEW.recorded_at >= m.recorded_at
                AND (((NEW.unit_cost_micros)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((m.unit_cost_micros)::TEXT COLLATE "C")) AND (((NEW.currency)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((m.currency)::TEXT COLLATE "C")) AND (((NEW.pack_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((m.pack_id)::TEXT COLLATE "C")) AND (((NEW.supplier_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((m.supplier_id)::TEXT COLLATE "C"))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_stock_reversal_valid" BEFORE INSERT ON "stock_movements" FOR EACH ROW EXECUTE FUNCTION "guard_stock_reversal_valid"();

CREATE OR REPLACE FUNCTION "guard_stock_movement_position"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
DECLARE parent_lock BIGINT ; position_id BIGINT  DEFAULT NULL;
BEGIN
            SELECT id INTO parent_lock FROM drug_batches WHERE id = NEW.batch_id FOR UPDATE;
            SELECT store_id INTO position_id FROM stock_position_heads h WHERE h.store_id = NEW.store_id AND h.batch_id = NEW.batch_id FOR UPDATE;
            IF position_id IS NULL THEN INSERT INTO stock_position_heads (store_id,batch_id) VALUES (NEW.store_id,NEW.batch_id); END IF;IF (EXISTS (SELECT 1 FROM stock_position_heads h WHERE h.store_id = NEW.store_id AND h.batch_id = NEW.batch_id
            AND h.quantity_micros + NEW.quantity_micros BETWEEN 0 AND 999999999999999
            AND (h.recorded_at IS NULL OR NEW.recorded_at >= h.recorded_at) FOR UPDATE)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g004_stock_movement_position" BEFORE INSERT ON "stock_movements" FOR EACH ROW EXECUTE FUNCTION "guard_stock_movement_position"();

CREATE OR REPLACE FUNCTION "guard_stock_document_movement"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.reference_type = 'stock_operation_line'
            AND NOT EXISTS (SELECT 1 FROM stock_operation_lines l JOIN stock_operations o ON o.id = l.operation_id
                WHERE (((NEW.reference_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  (((l.id)::TEXT)::TEXT COLLATE "C")) AND o.status = 'posting' AND o.reviewed_by = NEW.created_by
                    AND NEW.recorded_at = o.last_changed_at AND NEW.reversal_of IS NULL
                    AND NEW.drug_id = l.drug_id AND NEW.batch_id = l.batch_id AND (((NEW.currency)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  (((CASE WHEN l.unit_cost_micros IS NULL THEN NULL ELSE o.currency END))::TEXT COLLATE "C")) AND (((NEW.unit_cost_micros)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((l.unit_cost_micros)::TEXT COLLATE "C")) AND (((NEW.pack_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((l.pack_id)::TEXT COLLATE "C")) AND (((NEW.supplier_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((o.supplier_id)::TEXT COLLATE "C"))
                    AND ((NEW.store_id = o.destination_store_id AND NEW.quantity_micros = l.quantity_micros)
                        OR (NEW.store_id = o.source_store_id AND NEW.quantity_micros = -l.quantity_micros))
                    AND NEW.kind = CASE WHEN o.kind IN ('transfer','requisition') THEN 'transfer'
                        WHEN o.kind IN ('adjustment_in','adjustment_out') THEN 'adjustment' ELSE o.kind END) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g005_stock_document_movement" BEFORE INSERT ON "stock_movements" FOR EACH ROW EXECUTE FUNCTION "guard_stock_document_movement"();

