CREATE OR REPLACE FUNCTION "guard_stock_movement_advance"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN UPDATE stock_position_heads SET
            quantity_micros = quantity_micros + NEW.quantity_micros, movement_count = movement_count + 1,
            last_id = NEW.id, recorded_at = NEW.recorded_at WHERE store_id = NEW.store_id AND batch_id = NEW.batch_id; RETURN NEW; END;
$guard$;

