                IF NEW.reference_type = 'stock_operation_line' THEN INSERT INTO stock_operation_legs (line_id,store_id,movement_id)
                    VALUES ((NEW.reference_id)::BIGINT,NEW.store_id,NEW.id); END IF; RETURN NEW; END;
