CREATE OR REPLACE FUNCTION "guard_stock_leg_identity"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NOT EXISTS (SELECT 1 FROM stock_movements m
            JOIN stock_operation_lines l ON (((m.reference_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  (((l.id)::TEXT)::TEXT COLLATE "C")) JOIN stock_operations o ON o.id = l.operation_id
            WHERE m.id = NEW.movement_id AND m.reference_type = 'stock_operation_line' AND NEW.line_id = l.id
                AND m.store_id = NEW.store_id AND o.status = 'posting') THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

