CREATE OR REPLACE FUNCTION "guard_stock_line_identity"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.id <> OLD.id OR NEW.operation_id <> OLD.operation_id THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_stock_line_identity" BEFORE UPDATE ON "stock_operation_lines" FOR EACH ROW EXECUTE FUNCTION "guard_stock_line_identity"();

CREATE OR REPLACE FUNCTION "guard_stock_line_values_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.quantity_micros BETWEEN 1 AND 999999999999999
                AND NEW.drug_version > 0 AND (NEW.unit_cost_micros IS NULL OR NEW.unit_cost_micros BETWEEN 0 AND 999999999999999)
                AND ((NEW.pack_id IS NULL AND NEW.pack_count_micros IS NULL)
                    OR (NEW.pack_id IS NOT NULL AND NEW.pack_count_micros BETWEEN 1 AND 999999999999999))
                AND EXISTS (SELECT 1 FROM stock_operations o WHERE o.id = NEW.operation_id
                    AND (o.source_store_id IS NULL OR NEW.source_balance_version IS NOT NULL)
                    AND (NEW.unit_cost_micros IS NULL OR o.currency IS NOT NULL)
                    AND (o.kind NOT IN ('receipt','opening') OR (NEW.unit_cost_micros IS NOT NULL AND o.currency IS NOT NULL)))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_stock_line_values_update" BEFORE UPDATE ON "stock_operation_lines" FOR EACH ROW EXECUTE FUNCTION "guard_stock_line_values_update"();

CREATE OR REPLACE FUNCTION "guard_stock_line_draft_delete"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NOT EXISTS (SELECT 1 FROM stock_operations o WHERE o.id = OLD.operation_id AND o.status = 'draft') THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN OLD; END;
$guard$;

CREATE TRIGGER "g001_stock_line_draft_delete" BEFORE DELETE ON "stock_operation_lines" FOR EACH ROW EXECUTE FUNCTION "guard_stock_line_draft_delete"();

CREATE OR REPLACE FUNCTION "guard_stock_revision_current"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version > 0 AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000
            AND EXISTS (SELECT 1 FROM stock_operations o WHERE o.id = NEW.operation_id AND o.version = NEW.version
                AND o.last_actor_id = NEW.actor_id AND o.last_changed_at = NEW.recorded_at)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_stock_revision_current" BEFORE INSERT ON "stock_operation_revisions" FOR EACH ROW EXECUTE FUNCTION "guard_stock_revision_current"();

CREATE OR REPLACE FUNCTION "guard_stock_operation_revisions_immutable"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF 1 = 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_stock_operation_revisions_immutable" BEFORE UPDATE ON "stock_operation_revisions" FOR EACH ROW EXECUTE FUNCTION "guard_stock_operation_revisions_immutable"();

