CREATE TRIGGER "g001_stock_operation_revisions_retain" BEFORE DELETE ON "stock_operation_revisions" FOR EACH ROW EXECUTE FUNCTION "guard_stock_operation_revisions_retain"();

CREATE OR REPLACE FUNCTION "guard_stock_operation_valid_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version BETWEEN 1 AND 4294967294 AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000
                AND CHAR_LENGTH(trim(NEW.reference)) BETWEEN 1 AND 128 AND NEW.last_changed_at >= NEW.prepared_at
                AND ((NEW.kind IN ('receipt','opening','adjustment_in') AND NEW.source_store_id IS NULL AND NEW.source_store_version IS NULL
                    AND NEW.destination_store_id IS NOT NULL AND NEW.destination_store_version > 0)
                    OR (NEW.kind IN ('damage','expiry','adjustment_out') AND NEW.source_store_id IS NOT NULL AND NEW.source_store_version > 0
                        AND NEW.destination_store_id IS NULL AND NEW.destination_store_version IS NULL)
                    OR (NEW.kind IN ('transfer','requisition') AND NEW.source_store_id IS NOT NULL AND NEW.destination_store_id IS NOT NULL
                        AND NEW.source_store_id <> NEW.destination_store_id AND NEW.source_store_version > 0 AND NEW.destination_store_version > 0))
                AND ((NEW.kind = 'receipt' AND NEW.supplier_id IS NOT NULL AND NEW.supplier_version > 0
                        AND CHAR_LENGTH(trim(NEW.invoice_number)) BETWEEN 1 AND 128 AND NEW.currency IS NOT NULL)
                    OR (NEW.kind <> 'receipt' AND NEW.supplier_id IS NULL AND NEW.supplier_version IS NULL AND NEW.invoice_number IS NULL))
                AND (NEW.currency IS NULL OR REGEXP_LIKE(NEW.currency, '^[A-Z]{3}$', 'c'))
                AND ((NEW.status IN ('draft','submitted','cancelled') AND NEW.reviewed_by IS NULL AND NEW.reviewed_at IS NULL AND NEW.posted_at IS NULL)
                    OR (NEW.status IN ('posting','posted','rejected') AND NEW.reviewed_by IS NOT NULL AND NEW.reviewed_by <> NEW.prepared_by
                        AND NEW.reviewed_at >= NEW.prepared_at AND NEW.last_changed_at >= NEW.reviewed_at
                        AND ((NEW.status = 'posted' AND NEW.posted_at >= NEW.reviewed_at AND NEW.last_changed_at >= NEW.posted_at)
                            OR (NEW.status <> 'posted' AND NEW.posted_at IS NULL))))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_stock_operation_valid_insert" BEFORE INSERT ON "stock_operations" FOR EACH ROW EXECUTE FUNCTION "guard_stock_operation_valid_insert"();

CREATE OR REPLACE FUNCTION "guard_stock_operation_initial"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.status = 'draft' AND NEW.version = 1
            AND NEW.last_actor_id = NEW.prepared_by AND NEW.last_changed_at = NEW.prepared_at) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_stock_operation_initial" BEFORE INSERT ON "stock_operations" FOR EACH ROW EXECUTE FUNCTION "guard_stock_operation_initial"();

CREATE OR REPLACE FUNCTION "guard_stock_operation_valid_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version BETWEEN 1 AND 4294967294 AND CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000
                AND CHAR_LENGTH(trim(NEW.reference)) BETWEEN 1 AND 128 AND NEW.last_changed_at >= NEW.prepared_at
                AND ((NEW.kind IN ('receipt','opening','adjustment_in') AND NEW.source_store_id IS NULL AND NEW.source_store_version IS NULL
                    AND NEW.destination_store_id IS NOT NULL AND NEW.destination_store_version > 0)
                    OR (NEW.kind IN ('damage','expiry','adjustment_out') AND NEW.source_store_id IS NOT NULL AND NEW.source_store_version > 0
                        AND NEW.destination_store_id IS NULL AND NEW.destination_store_version IS NULL)
                    OR (NEW.kind IN ('transfer','requisition') AND NEW.source_store_id IS NOT NULL AND NEW.destination_store_id IS NOT NULL
                        AND NEW.source_store_id <> NEW.destination_store_id AND NEW.source_store_version > 0 AND NEW.destination_store_version > 0))
                AND ((NEW.kind = 'receipt' AND NEW.supplier_id IS NOT NULL AND NEW.supplier_version > 0
                        AND CHAR_LENGTH(trim(NEW.invoice_number)) BETWEEN 1 AND 128 AND NEW.currency IS NOT NULL)
                    OR (NEW.kind <> 'receipt' AND NEW.supplier_id IS NULL AND NEW.supplier_version IS NULL AND NEW.invoice_number IS NULL))
                AND (NEW.currency IS NULL OR REGEXP_LIKE(NEW.currency, '^[A-Z]{3}$', 'c'))
                AND ((NEW.status IN ('draft','submitted','cancelled') AND NEW.reviewed_by IS NULL AND NEW.reviewed_at IS NULL AND NEW.posted_at IS NULL)
                    OR (NEW.status IN ('posting','posted','rejected') AND NEW.reviewed_by IS NOT NULL AND NEW.reviewed_by <> NEW.prepared_by
                        AND NEW.reviewed_at >= NEW.prepared_at AND NEW.last_changed_at >= NEW.reviewed_at
                        AND ((NEW.status = 'posted' AND NEW.posted_at >= NEW.reviewed_at AND NEW.last_changed_at >= NEW.posted_at)
                            OR (NEW.status <> 'posted' AND NEW.posted_at IS NULL))))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
