CREATE OR REPLACE FUNCTION "guard_stock_operation_transition"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NOT (((NEW.id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.id)::TEXT COLLATE "C")) OR NOT (((NEW.kind)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.kind)::TEXT COLLATE "C")) OR NOT (((NEW.prepared_by)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.prepared_by)::TEXT COLLATE "C")) OR NOT (((NEW.prepared_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.prepared_at)::TEXT COLLATE "C"))) OR NEW.version <> OLD.version + 1
            OR NEW.last_changed_at < OLD.last_changed_at OR (OLD.status <> 'draft' AND (NOT (((NEW.source_store_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.source_store_id)::TEXT COLLATE "C")) OR NOT (((NEW.destination_store_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.destination_store_id)::TEXT COLLATE "C")) OR NOT (((NEW.source_store_version)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.source_store_version)::TEXT COLLATE "C")) OR NOT (((NEW.destination_store_version)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.destination_store_version)::TEXT COLLATE "C")) OR NOT (((NEW.supplier_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.supplier_id)::TEXT COLLATE "C")) OR NOT (((NEW.supplier_version)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.supplier_version)::TEXT COLLATE "C")) OR NOT (((NEW.invoice_number)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.invoice_number)::TEXT COLLATE "C")) OR NOT (((NEW.currency)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.currency)::TEXT COLLATE "C")) OR NOT (((NEW.reference)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.reference)::TEXT COLLATE "C")) OR NOT (((NEW.catalog_snapshot)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.catalog_snapshot)::TEXT COLLATE "C"))))
            OR NOT ((OLD.status = 'draft' AND NEW.status IN ('draft','submitted','cancelled') AND NEW.last_actor_id = OLD.prepared_by)
                OR (OLD.status = 'submitted' AND NEW.status = 'cancelled' AND NEW.last_actor_id = OLD.prepared_by)
                OR (OLD.status = 'submitted' AND NEW.status IN ('posting','rejected') AND NEW.last_actor_id = NEW.reviewed_by)
                OR (OLD.status = 'posting' AND NEW.status = 'posted' AND NEW.reviewed_by = OLD.reviewed_by
                    AND NEW.reviewed_at = OLD.reviewed_at AND NEW.last_actor_id = OLD.reviewed_by)) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_stock_operation_transition" BEFORE UPDATE ON "stock_operations" FOR EACH ROW EXECUTE FUNCTION "guard_stock_operation_transition"();

CREATE OR REPLACE FUNCTION "guard_stock_document_posted"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.status = 'posted' AND (
            NOT EXISTS (SELECT 1 FROM stock_operation_lines l WHERE l.operation_id = NEW.id)
            OR EXISTS (SELECT 1 FROM stock_operation_lines l WHERE l.operation_id = NEW.id AND
                (SELECT COUNT(*) FROM stock_operation_legs m WHERE m.line_id = l.id)
                    <> CASE WHEN NEW.kind IN ('transfer','requisition') THEN 2 ELSE 1 END)
            OR (NEW.kind = 'receipt' AND NOT EXISTS (SELECT 1 FROM stock_invoice_receipts i WHERE i.operation_id = NEW.id))) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Stock operation integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_stock_document_posted" BEFORE UPDATE ON "stock_operations" FOR EACH ROW EXECUTE FUNCTION "guard_stock_document_posted"();

