CREATE OR REPLACE FUNCTION "guard_stock_position_initial"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.quantity_micros = 0 AND NEW.movement_count = 0
            AND NEW.last_id IS NULL AND NEW.recorded_at IS NULL) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_stock_position_initial" BEFORE INSERT ON "stock_position_heads" FOR EACH ROW EXECUTE FUNCTION "guard_stock_position_initial"();

CREATE OR REPLACE FUNCTION "guard_stock_position_advance_only"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.store_id = OLD.store_id AND NEW.batch_id = OLD.batch_id
            AND NEW.last_id > COALESCE(OLD.last_id,0) AND NEW.movement_count = OLD.movement_count + 1
            AND NEW.quantity_micros BETWEEN 0 AND 999999999999999
            AND EXISTS (SELECT 1 FROM stock_movements m WHERE m.id = NEW.last_id AND m.store_id = NEW.store_id AND m.batch_id = NEW.batch_id
                AND NEW.quantity_micros = OLD.quantity_micros + m.quantity_micros AND NEW.recorded_at = m.recorded_at)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

