                IF (NEW.kind IN ('pack','price') AND NEW.version = 0
            AND NEW.last_id IS NULL AND NEW.recorded_at IS NULL AND NEW.effective_at IS NULL) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

