CREATE OR REPLACE FUNCTION "guard_stock_series_advance_only"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.drug_id = OLD.drug_id AND NEW.kind = OLD.kind AND NEW.code = OLD.code
            AND NEW.version = OLD.version + 1 AND NEW.last_id > COALESCE(OLD.last_id,0)
            AND ((NEW.kind = 'pack' AND (((NEW.effective_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((NULL)::TEXT COLLATE "C")) AND EXISTS (SELECT 1 FROM drug_packs p WHERE p.id = NEW.last_id
                AND p.drug_id = NEW.drug_id AND p.code = NEW.code AND p.version = NEW.version AND p.recorded_at = NEW.recorded_at))
                OR (NEW.kind = 'price' AND EXISTS (SELECT 1 FROM drug_prices p WHERE p.id = NEW.last_id
                    AND p.drug_id = NEW.drug_id AND (CONCAT(p.kind, ':', p.currency)) = NEW.code AND p.version = NEW.version
                    AND p.recorded_at = NEW.recorded_at AND (((NEW.effective_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((p.effective_at)::TEXT COLLATE "C")))))) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

