CREATE OR REPLACE FUNCTION "guard_stock_stores_version"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NOT (((NEW.id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.id)::TEXT COLLATE "C")) OR NOT (((NEW.code)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.code)::TEXT COLLATE "C")) OR NOT (((NEW.created_by)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_by)::TEXT COLLATE "C")) OR NOT (((NEW.recorded_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.recorded_at)::TEXT COLLATE "C")) OR NOT (((NEW.reason)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.reason)::TEXT COLLATE "C")) OR NOT (((NEW.department_id)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.department_id)::TEXT COLLATE "C")) OR NOT (((NEW.kind)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.kind)::TEXT COLLATE "C")) OR NEW.version <> OLD.version + 1 OR NEW.updated_at < OLD.updated_at THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_stock_stores_version" BEFORE UPDATE ON "stock_stores" FOR EACH ROW EXECUTE FUNCTION "guard_stock_stores_version"();

CREATE OR REPLACE FUNCTION "guard_stock_stores_retain"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF 1 = 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN OLD; END;
$guard$;

CREATE TRIGGER "g001_stock_stores_retain" BEFORE DELETE ON "stock_stores" FOR EACH ROW EXECUTE FUNCTION "guard_stock_stores_retain"();

CREATE OR REPLACE FUNCTION "guard_stock_units_provenance"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (CHAR_LENGTH(trim(NEW.reason)) BETWEEN 5 AND 2000 AND NEW.recorded_at IS NOT NULL) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
$guard$;

