BEGIN
                IF (NEW.is_active IN (0,1) AND NEW.version BETWEEN 1 AND 4294967294
                AND CHAR_LENGTH(trim(NEW.change_reason)) BETWEEN 5 AND 2000 AND NEW.updated_at >= NEW.recorded_at
                AND CHAR_LENGTH(trim(NEW.name)) BETWEEN 1 AND 191) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Medication stock integrity violation'; END IF; RETURN NEW; END;
