CREATE OR REPLACE FUNCTION "guard_vital_signs_lock_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
DECLARE locked_id BIGINT ;
BEGIN
                SELECT id INTO locked_id FROM clinical_records WHERE id = NEW.clinical_record_id FOR UPDATE; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_vital_signs_lock_insert" BEFORE INSERT ON "vital_signs" FOR EACH ROW EXECUTE FUNCTION "guard_vital_signs_lock_insert"();

CREATE OR REPLACE FUNCTION "guard_vital_signs_draft_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NOT EXISTS (SELECT 1 FROM clinical_records r WHERE r.id = NEW.clinical_record_id AND r.kind = 'vitals' AND r.status = 'draft' FOR UPDATE) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Only matching draft clinical content can be written.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_vital_signs_draft_insert" BEFORE INSERT ON "vital_signs" FOR EACH ROW EXECUTE FUNCTION "guard_vital_signs_draft_insert"();

CREATE OR REPLACE FUNCTION "guard_vital_signs_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.observed_at IS NOT NULL
            AND ((NEW.systolic_mmhg IS NULL AND NEW.diastolic_mmhg IS NULL) OR (NEW.systolic_mmhg BETWEEN 1 AND 65535 AND NEW.diastolic_mmhg BETWEEN 1 AND 65535))
            AND (NEW.weight_kg IS NULL OR NEW.weight_kg > 0) AND (NEW.height_m IS NULL OR NEW.height_m > 0)
            AND ((NEW.blood_glucose IS NULL AND NEW.blood_glucose_unit IS NULL)
                OR (NEW.blood_glucose >= 0 AND NEW.blood_glucose_unit IN ('mg/dL', 'mmol/L')))
            AND (NEW.pulse_bpm IS NULL OR NEW.pulse_bpm >= 0) AND (NEW.respiratory_rate IS NULL OR NEW.respiratory_rate >= 0)
            AND (NEW.spo2_percent IS NULL OR NEW.spo2_percent BETWEEN 0 AND 100)
            AND (NEW.fetal_heart_rate IS NULL OR NEW.fetal_heart_rate >= 0)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid clinical storage value.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_vital_signs_validate_insert" BEFORE INSERT ON "vital_signs" FOR EACH ROW EXECUTE FUNCTION "guard_vital_signs_validate_insert"();

CREATE OR REPLACE FUNCTION "guard_vital_signs_lock_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
DECLARE locked_id BIGINT ;
BEGIN
                SELECT id INTO locked_id FROM clinical_records WHERE id = NEW.clinical_record_id FOR UPDATE; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_vital_signs_lock_update" BEFORE UPDATE ON "vital_signs" FOR EACH ROW EXECUTE FUNCTION "guard_vital_signs_lock_update"();

CREATE OR REPLACE FUNCTION "guard_vital_signs_draft_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF NOT EXISTS (SELECT 1 FROM clinical_records r WHERE r.id = NEW.clinical_record_id AND r.kind = 'vitals' AND r.status = 'draft' FOR UPDATE) OR NEW.clinical_record_id <> OLD.clinical_record_id THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Only matching draft clinical content can be written.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_vital_signs_draft_update" BEFORE UPDATE ON "vital_signs" FOR EACH ROW EXECUTE FUNCTION "guard_vital_signs_draft_update"();

CREATE OR REPLACE FUNCTION "guard_vital_signs_validate_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF (NEW.observed_at IS NOT NULL
            AND ((NEW.systolic_mmhg IS NULL AND NEW.diastolic_mmhg IS NULL) OR (NEW.systolic_mmhg BETWEEN 1 AND 65535 AND NEW.diastolic_mmhg BETWEEN 1 AND 65535))
            AND (NEW.weight_kg IS NULL OR NEW.weight_kg > 0) AND (NEW.height_m IS NULL OR NEW.height_m > 0)
            AND ((NEW.blood_glucose IS NULL AND NEW.blood_glucose_unit IS NULL)
                OR (NEW.blood_glucose >= 0 AND NEW.blood_glucose_unit IN ('mg/dL', 'mmol/L')))
            AND (NEW.pulse_bpm IS NULL OR NEW.pulse_bpm >= 0) AND (NEW.respiratory_rate IS NULL OR NEW.respiratory_rate >= 0)
            AND (NEW.spo2_percent IS NULL OR NEW.spo2_percent BETWEEN 0 AND 100)
            AND (NEW.fetal_heart_rate IS NULL OR NEW.fetal_heart_rate >= 0)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid clinical storage value.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_vital_signs_validate_update" BEFORE UPDATE ON "vital_signs" FOR EACH ROW EXECUTE FUNCTION "guard_vital_signs_validate_update"();

CREATE OR REPLACE FUNCTION "guard_vital_signs_no_delete"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN IF 1 = 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Clinical content is retained.'; END IF; RETURN OLD; END;
$guard$;

CREATE TRIGGER "g001_vital_signs_no_delete" BEFORE DELETE ON "vital_signs" FOR EACH ROW EXECUTE FUNCTION "guard_vital_signs_no_delete"();

CREATE OR REPLACE FUNCTION "guard_wards_validate_insert"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version BETWEEN 1 AND 4294967294 AND NEW.is_active IN (0, 1) AND (NEW.daily_rate IS NULL OR (NEW.daily_rate >= 0 AND NEW.daily_rate <= 999999999999.99 AND round(NEW.daily_rate, 2) = NEW.daily_rate)) AND CHAR_LENGTH(trim(NEW.code)) BETWEEN 1 AND 64 AND CHAR_LENGTH(trim(NEW.name)) BETWEEN 1 AND 191 AND (NEW.type IS NULL OR CHAR_LENGTH(trim(NEW.type)) BETWEEN 1 AND 64)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid admission storage record.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_wards_validate_insert" BEFORE INSERT ON "wards" FOR EACH ROW EXECUTE FUNCTION "guard_wards_validate_insert"();

CREATE OR REPLACE FUNCTION "guard_wards_start_version"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.version <> 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Catalog records must start at version one.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_wards_start_version" BEFORE INSERT ON "wards" FOR EACH ROW EXECUTE FUNCTION "guard_wards_start_version"();

CREATE OR REPLACE FUNCTION "guard_wards_validate_update"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF (NEW.version BETWEEN 1 AND 4294967294 AND NEW.is_active IN (0, 1) AND (NEW.daily_rate IS NULL OR (NEW.daily_rate >= 0 AND NEW.daily_rate <= 999999999999.99 AND round(NEW.daily_rate, 2) = NEW.daily_rate)) AND CHAR_LENGTH(trim(NEW.code)) BETWEEN 1 AND 64 AND CHAR_LENGTH(trim(NEW.name)) BETWEEN 1 AND 191 AND (NEW.type IS NULL OR CHAR_LENGTH(trim(NEW.type)) BETWEEN 1 AND 64)) IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Invalid admission storage record.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g001_wards_validate_update" BEFORE UPDATE ON "wards" FOR EACH ROW EXECUTE FUNCTION "guard_wards_validate_update"();

CREATE OR REPLACE FUNCTION "guard_wards_preserve_identity"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.id <> OLD.id OR NOT (((NEW.code)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.code)::TEXT COLLATE "C")) OR NOT (((NEW.created_at)::TEXT COLLATE "C")  IS NOT DISTINCT FROM  ((OLD.created_at)::TEXT COLLATE "C")) OR NEW.version <> OLD.version + 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Catalog identity or version is invalid.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g002_wards_preserve_identity" BEFORE UPDATE ON "wards" FOR EACH ROW EXECUTE FUNCTION "guard_wards_preserve_identity"();

CREATE OR REPLACE FUNCTION "guard_wards_retire_empty"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF NEW.is_active = 0 AND EXISTS
            (SELECT 1 FROM beds b JOIN bed_allocations a ON a.bed_id = b.id WHERE b.ward_id = OLD.id AND a.released_at IS NULL FOR UPDATE) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Occupied wards cannot be retired.'; END IF; RETURN NEW; END;
$guard$;

CREATE TRIGGER "g003_wards_retire_empty" BEFORE UPDATE ON "wards" FOR EACH ROW EXECUTE FUNCTION "guard_wards_retire_empty"();

CREATE OR REPLACE FUNCTION "guard_wards_retain_history"() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, easycare, extensions AS $guard$
BEGIN
                IF 1 = 1 THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Admission and location records cannot be deleted.'; END IF; RETURN OLD; END;
$guard$;

CREATE TRIGGER "g001_wards_retain_history" BEFORE DELETE ON "wards" FOR EACH ROW EXECUTE FUNCTION "guard_wards_retain_history"();

CREATE TRIGGER "guard_current_bed_occupancies_readonly" INSTEAD OF INSERT OR UPDATE OR DELETE ON "current_bed_occupancies" FOR EACH ROW EXECUTE FUNCTION guard_audit_events_no_update();

CREATE TRIGGER "guard_stock_balances_readonly" INSTEAD OF INSERT OR UPDATE OR DELETE ON "stock_balances" FOR EACH ROW EXECUTE FUNCTION guard_audit_events_no_update();
